// ---- 09-drag-preview.js ----
// Module 09: Drag Preview Subsystem

let dragStartData = null; // Temp storage for drag start data
const PREVIEW_WIN_NAME = 'PicKitPreviewWindow';

// 1. Handle drag start
function handleLinkDragStart(e) {
    if (!getConfig('enableDragPreview')) return;

    // Precise check: must be left-button drag on a hyperlink (or inside one)
    const link = e.target.closest('a[href]');

    // Exclude invalid links (e.g., javascript:void(0) or anchors)
    if (!link || !link.href || link.href.startsWith('javascript:') || link.href.startsWith('#')) {
        dragStartData = null;
        return;
    }

    dragStartData = {
        url: link.href,
        x: e.clientX,
        y: e.clientY,
        timestamp: Date.now()
    };
}

// 2. Handle drag end
function handleLinkDragEnd(e) {
    if (!dragStartData) return;

    const { x: startX, y: startY, url } = dragStartData;
    const endX = e.clientX;
    const endY = e.clientY;

    /* ---------- 1. Outside viewport: discard ---------- */
    if (
        endX < 0 || endY < 0 ||
        endX > window.innerWidth || endY > window.innerHeight
    ) {
        dragStartData = null;
        return;
    }

    /* ---------- 2. Input area / rich text / drop container filter ---------- */
    const target = document.elementFromPoint(endX, endY);
    if (target) {
        // 2-1 Input fields
        if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
            dragStartData = null;
            return;
        }
        // 2-2 Rich text editing
        if (target.closest('[contenteditable="true"]')) {
            dragStartData = null;
            return;
        }
        // 2-3 Container with dragover / drop events
        const dropZone = target.closest('[ondragover],[ondrop]');
        if (dropZone) {
            dragStartData = null;
            return;
        }
    }

    /* ---------- 3. Distance threshold check ---------- */
    const dist = Math.hypot(endX - startX, endY - startY);
    if (dist > 30) openPreviewWindow(url); // Distance threshold: 30px
    // Clean up data
    dragStartData = null;
}

// 3. Open preview window
async function openPreviewWindow(url) {
    const screen = window.screen;
    const screenW = screen.availWidth;
    const screenH = screen.availHeight;
    const screenLeft = screen.availLeft || 0;
    const screenTop = screen.availTop || 0;

    // Golden ratio
    const GOLDEN_RATIO = 0.618;

    const width = Math.round(screenW * GOLDEN_RATIO);
    const height = Math.round(screenH * GOLDEN_RATIO);

    const left = screenLeft + (screenW - width) / 2;
    const top = screenTop + (screenH - height) / 2;

    const features = `width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes,status=yes`;
    window.open(url, PREVIEW_WIN_NAME, features);
}


// ---- 10-unlock-mode.js ----
// Module 10: Unlock Mode / Super Selection

let isUnlockMode = false;
let unlockStyleEl = null;
let startPos = { x: 0, y: 0 };
const modifiedElements = new Set(); // Set of affected elements

// The default Ctrl hotkey also fires on Ctrl+V. Unlock mode changes global
// selection behavior and used to clear the document selection on exit, which
// left focused inputs/contenteditable editors without a caret.
let unlockFocusSnapshot = null;
let unlockUserInteracted = false;

function isEditableElement(el) {
    if (!el || !el.isConnected) return false;
    if (el.isContentEditable) return true;
    return (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') && !el.disabled && !el.readOnly;
}

function captureUnlockFocus() {
    const el = document.activeElement;
    if (!isEditableElement(el)) return null;
    if (el.isContentEditable) {
        const sel = window.getSelection();
        const range = sel && sel.rangeCount > 0 ? sel.getRangeAt(0) : null;
        return {
            element: el,
            range: range && el.contains(range.commonAncestorContainer) ? range.cloneRange() : null
        };
    }
    return { element: el, start: el.selectionStart, end: el.selectionEnd };
}

function restoreUnlockFocus(snapshot) {
    if (!snapshot || !snapshot.element || !snapshot.element.isConnected) return;
    if (unlockUserInteracted) return;
    // Do not pull focus back into the page if the whole window was blurred.
    if (typeof document.hasFocus === 'function' && !document.hasFocus()) return;

    // Only react when the hotkey actually stole focus. If the input still owns
    // the selection, leave it alone so a just-pasted caret is not moved back.
    const active = document.activeElement;
    const focusLost = active !== snapshot.element &&
        (active === document.body || active === document.documentElement || !active);
    if (!focusLost) return;

    try {
        snapshot.element.focus({ preventScroll: true });
        // Inputs/textarea keep selectionStart/End through a blur. For a
        // contenteditable with no live range, put the caret back where it was.
        if (snapshot.range) {
            const sel = window.getSelection();
            if (sel && sel.rangeCount === 0) {
                sel.addRange(snapshot.range);
            }
        }
    } catch (e) {}
}

// Dynamic CSS: force text selectable, block drag, disable pointer event restrictions, etc.
function getUnlockCSS() {
    return `
        /* --- 1. Global force selectable (separate cursor settings) --- */
        html, body, *:not([data-tm-policy="protected"]), [unselectable] {
            user-select: text !important;
            -webkit-user-select: text !important;
            -moz-user-select: text !important;
            -ms-user-select: text !important;
        }

        /* Fix: html/body keep default cursor to avoid global pollution */
        html, body {
            cursor: default !important;
        }

        /* Fix: text cursor only for actual text elements */
        p, span, div, h1, h2, h3, h4, h5, h6, li, td, th, pre, code,
        blockquote, article, section, main, aside, header, footer,
        nav, figcaption, label, time, mark, em, strong, i, b, u,
        s, small, cite, dfn, abbr, data, q, sub, sup, kbd, samp,
        var, output, details, summary, address, dl, dt, dd,
        fieldset, legend, caption, tbody, thead, tfoot, tr,
        button:not([disabled]),
        a:not([data-tm-policy="protected"]) {
            cursor: text !important;
        }

        /* Force highlight color */
        ::selection {background-color: #3390FF !important;color: #ffffff !important;text-shadow: none !important;}
        ::-moz-selection {background-color: #3390FF !important;color: #ffffff !important;text-shadow: none !important;}

        /* Make links look like plain text, block image/link dragging (interferes with text selection) */
        a:not([data-tm-policy="protected"]),
        a *:not([data-tm-policy="protected"]),
        img:not([data-tm-policy="protected"]){
            pointer-events: auto !important;
            user-drag: none !important;
            -webkit-user-drag: none !important;
            text-decoration: none !important;
        }

        /* Disable interaction on common transparent overlays so clicks reach text below */
        div[style*="z-index"][style*="fixed"]:not([data-tm-policy="protected"]),
        div[style*="z-index"][style*="absolute"]:not([data-tm-policy="protected"]) {
            pointer-events: none !important;
        }

        /* Do NOT blanket-force pointer-events: auto here. Re-enabling it on every
           div re-arms invisible full-screen overlays that pages keep at
           pointer-events: none (e.g. CSDN's .layout-main-content-overlay), which
           then swallow every mousedown and make the page unselectable. */

        /* Style for expanded truncated text: hide scrollbar but keep scroll functionality */
        .tm-sc-expanded {
            scrollbar-width: none !important;
            -ms-overflow-style: none !important;
        }
        .tm-sc-expanded::-webkit-scrollbar {
            display: none !important;
            width: 0 !important;
            height: 0 !important;
        }

        a.absolute, a[style*="position: absolute"] { pointer-events: none !important; }

        /* Protected marker takes highest priority */
        [data-tm-policy="protected"][data-tm-policy="protected"][data-tm-policy="protected"],
        [data-tm-policy="protected"][data-tm-policy="protected"][data-tm-policy="protected"] * {
            user-select: none !important;
            -webkit-user-select: none !important;
            -moz-user-select: none !important;
            pointer-events: none !important;
            cursor: default !important;
            z-index: 2147483647 !important;
        }
    `;
}

// Check if element is protected
function isProtectedElement(target) {
    return target && target.closest && target.closest('[data-tm-policy="protected"]');
}

function handleCaptureSelectStart(e) {
    if (!isUnlockMode) return;
    if (isProtectedElement(e.target)) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        return;
    }
    e.stopPropagation();
    e.stopImmediatePropagation();
}

// Intercept click events: prevent if drag operation or link click
function handleCaptureClick(e) {
    if (!isUnlockMode) return;
    if (isProtectedElement(e.target)) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        return;
    }
    const dx = Math.abs(e.clientX - startPos.x);
    const dy = Math.abs(e.clientY - startPos.y);
    const isDrag = dx > 3 || dy > 3;

    let target = e.target;
    let isLink = false;
    while (target && target !== document) {
        if (target.tagName === 'A') {
            isLink = true;
            break;
        }
        target = target.parentNode;
    }
    if (isDrag || isLink) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
    }
}

// Process current element on mousedown as needed
function handleCaptureMouseDown(e) {
    if (!isUnlockMode) return;
    unlockUserInteracted = true;
    if (isProtectedElement(e.target)) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        return;
    }
    const el = e.target;
    if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA')) {
        try {
            if (el.type === 'password') {
                el.dataset.scOriginalType = 'password';
                el.type = 'text';
                modifiedElements.add(el);
            }
            if (el.disabled) {
                el.disabled = false;
                el.dataset.scWasDisabled = 'true';
                modifiedElements.add(el);
            }
            if (el.readOnly) {
                el.readOnly = false;
                el.dataset.scWasReadOnly = 'true';
                modifiedElements.add(el);
            }
        } catch (err) {}
    }
    startPos = { x: e.clientX, y: e.clientY };
    e.stopPropagation();
    e.stopImmediatePropagation();
}

function handleCaptureDragStart(e) {
    if (!isUnlockMode) return;
    e.preventDefault();
    e.stopPropagation();
}

function handleCaptureCopy(e) {
    if (!isUnlockMode) return;
    e.stopImmediatePropagation();
}

function handleCaptureSelectionChange(e) {
    if (!isUnlockMode) return;
    e.stopPropagation();
    e.stopImmediatePropagation();
}

function cleanInlineEvents() {
    const targets = [document.documentElement, document.body];
    const events = ['onselectstart', 'onmousedown', 'oncontextmenu', 'oncopy'];
    targets.forEach(el => {
        if (!el) return;
        events.forEach(evt => {
            if (el.hasAttribute(evt)) {
                el.removeAttribute(evt);
            }
            if (el[evt]) {
                el[evt] = null;
            }
        });
    });
}

// Smart expand truncated text on mouse hover
function handleExpandHover(e) {
    if (!isUnlockMode) return;
    let target = e.target;
    if (target.nodeType !== 1 || target.classList.contains('tm-sc-expanded')) return;

    const style = window.getComputedStyle(target);
    const isEllipsis = style.textOverflow === 'ellipsis';
    const isLineClamp = style.webkitLineClamp && style.webkitLineClamp !== 'none';

    if (isEllipsis || isLineClamp) {
        const rect = target.getBoundingClientRect();
        target.style.setProperty('height', rect.height + 'px', 'important');
        target.style.setProperty('width', rect.width + 'px', 'important');
        target.classList.add('tm-sc-expanded');

        if (isLineClamp) {
            target.style.setProperty('-webkit-line-clamp', 'none', 'important');
            target.style.setProperty('overflow-y', 'auto', 'important');
        } else {
            target.style.setProperty('text-overflow', 'clip', 'important');
            target.style.setProperty('overflow-x', 'auto', 'important');
            target.style.setProperty('white-space', 'nowrap', 'important');
        }
    }
}

// Clean up all expanded elements when exiting mode
function cleanupExpandedElements() {
    const elements = document.querySelectorAll('.tm-sc-expanded');
    elements.forEach(el => {
        el.scrollTop = 0;
        el.scrollLeft = 0;
        el.classList.remove('tm-sc-expanded');
        el.style.removeProperty('height');
        el.style.removeProperty('width');
        el.style.removeProperty('-webkit-line-clamp');
        el.style.removeProperty('overflow-y');
        el.style.removeProperty('overflow-x');
        el.style.removeProperty('text-overflow');
        el.style.removeProperty('white-space');
    });
}

// Toggle unlock mode
function toggleUnlockMode(active) {
    if (active === isUnlockMode) return;
    isUnlockMode = active;

    if (active) {
        unlockFocusSnapshot = captureUnlockFocus();
        unlockUserInteracted = false;
        if (!unlockStyleEl) {
            unlockStyleEl = document.createElement('style');
            unlockStyleEl.textContent = getUnlockCSS();
            unlockStyleEl.id = 'tm-smart-copy-unlock-style';
        }
        (document.documentElement || document.body).appendChild(unlockStyleEl);
        cleanInlineEvents();

        window.addEventListener('selectstart', handleCaptureSelectStart, true);
        window.addEventListener('click', handleCaptureClick, true);
        window.addEventListener('mousedown', handleCaptureMouseDown, true);
        window.addEventListener('dragstart', handleCaptureDragStart, true);
        window.addEventListener('copy', handleCaptureCopy, true);
        window.addEventListener('contextmenu', handleCaptureCopy, true);
        document.addEventListener('selectionchange', handleCaptureSelectionChange, true);
        document.addEventListener('mouseover', handleExpandHover, true);

        showToast(t('toast_unlock'));
    } else {
        const focusSnapshot = unlockFocusSnapshot;
        unlockFocusSnapshot = null;
        if (unlockStyleEl && unlockStyleEl.parentNode) {
            unlockStyleEl.parentNode.removeChild(unlockStyleEl);
        }

        modifiedElements.forEach(el => {
            try {
                if (el.dataset.scOriginalType === 'password') {
                    el.type = 'password';
                    delete el.dataset.scOriginalType;
                }
                if (el.dataset.scWasDisabled === 'true') { el.disabled = true; delete el.dataset.scWasDisabled; }
                if (el.dataset.scWasReadOnly === 'true') { el.readOnly = true; delete el.dataset.scWasReadOnly; }
            } catch (e) {}
        });
        modifiedElements.clear();

        window.removeEventListener('selectstart', handleCaptureSelectStart, true);
        window.removeEventListener('mousedown', handleCaptureMouseDown, true);
        window.removeEventListener('click', handleCaptureClick, true);
        window.removeEventListener('dragstart', handleCaptureDragStart, true);
        window.removeEventListener('copy', handleCaptureCopy, true);
        window.removeEventListener('contextmenu', handleCaptureCopy, true);
        document.removeEventListener('selectionchange', handleCaptureSelectionChange, true);
        document.removeEventListener('mouseover', handleExpandHover, true);
        cleanupExpandedElements();

        // Clearing ranges while an editor is focused removes its caret. Keep
        // the untouched selection and restore focus if the hotkey stole it.
        if (!focusSnapshot && !isEditableElement(document.activeElement)) {
            const sel = window.getSelection();
            if (sel && sel.rangeCount > 0) {
                sel.removeAllRanges();
            }
        }
        restoreUnlockFocus(focusSnapshot);
        unlockUserInteracted = false;
        const toast = shadowRoot && shadowRoot.querySelector('.sc-toast');
        if (toast) toast.classList.remove('show');
    }
}

// Keyboard listener
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && isEditMode) {
        toggleEditMode(false);
        return;
    }
    const hotkey = getConfig('unlockHotkey');
    if (!hotkey) return;
    if (e.code === hotkey || e.key === hotkey) {
        if (!isUnlockMode) toggleUnlockMode(true);
    }
});

document.addEventListener('keyup', (e) => {
    const hotkey = getConfig('unlockHotkey');
    if (!hotkey) return;
    if (e.code === hotkey || e.key === hotkey) {
        if (isUnlockMode) toggleUnlockMode(false);
    }
});

window.addEventListener('blur', () => {
    if (isUnlockMode) toggleUnlockMode(false);
});


// ---- 11-clipboard.js ----
// Module 11: Clipboard & Toast

// Three-tier fallback copy strategy. Returns true only when the clipboard
// write is believed to have succeeded, so a cut can avoid deleting on failure.
async function copyToClipboard(text, html) {
    try {
        // Prefer ClipboardItem to preserve formatting (unless plain text)
        if (html && typeof ClipboardItem !== 'undefined') {
            const htmlBlob = new Blob([html], { type: 'text/html' });
            const textBlob = new Blob([text], { type: 'text/plain' });
            const data = [new ClipboardItem({ 'text/html': htmlBlob, 'text/plain': textBlob })];
            await navigator.clipboard.write(data);
        } else {
            // Fallback to plain text
            await navigator.clipboard.writeText(text);
        }
        return true;
    } catch (e) {
        // Fallback to privileged GM API GM_setClipboard
        if (typeof GM_setClipboard === 'function') {
            try {
                if (text) {
                    GM_setClipboard(text, 'text');
                } else {
                    GM_setClipboard(html, 'html');
                }
                return true;
            } catch (err) {}
        }
        return false;
    }
}

// Show toast (inside Shadow DOM)
function showToast(msg, duration = 1200) {
    if (!shadowRoot) initContainer();
    let toast = shadowRoot.querySelector('.sc-toast');
    if (!toast) {
        toast = document.createElement('div');
        toast.className = 'sc-toast';
        shadowRoot.appendChild(toast);
    }
    toast.textContent = '';
    if (msg && msg.nodeType) {
        toast.appendChild(msg);
    } else {
        toast.textContent = msg;
    }
    toast.classList.add('show');

    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
        toast.classList.remove('show');
    }, duration);
}


// ---- 12-theme.js ----
// Module 12: Background Brightness & Theme

// Smart page background brightness detection; returns 'light' or 'dark' to determine UI theme
// Logic: dark page background → return 'light' (light UI); light page background → return 'dark' (dark UI)
function getBestContrastTheme() {
    const getBgColor = (el) => {
        if (!el) return null;
        const style = window.getComputedStyle(el);
        return style.backgroundColor;
    };

    const getBrightness = (colorStr) => {
        if (!colorStr || colorStr === 'transparent' || colorStr === 'rgba(0, 0, 0, 0)') return null;
        const match = colorStr.match(/(\d+),\s*(\d+),\s*(\d+)/);
        if (!match) return null;
        const [r, g, b] = [parseInt(match[1]), parseInt(match[2]), parseInt(match[3])];
        // Calculate brightness (YIQ formula), range 0~255, lower = darker
        return (r * 299 + g * 587 + b * 114) / 1000;
    };

    // 1. Prefer body background
    let brightness = getBrightness(getBgColor(document.body));

    // 2. If body is transparent, check html (documentElement) background
    if (brightness === null) {
        brightness = getBrightness(getBgColor(document.documentElement));
    }

    // 3. If html is also transparent, fallback to system dark mode preference
    if (brightness === null) {
        const sysIsDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        return sysIsDark ? 'theme-light-ui' : 'theme-dark-ui';
    }

    // 4. Brightness < 128 (dark background) → use 'theme-light-ui' (light buttons)
    return brightness < 128 ? 'theme-light-ui' : 'theme-dark-ui';
}


// ---- 13-renderer.js ----
// Module 13: Button Renderer

const LINK_MENU_MAX = 12;
const LINK_DISPLAY_MAX = 42;

// Keep a multi-link menu readable without changing the real URL that opens.
function truncateLinkDisplay(text) {
    const chars = Array.from(text);
    return chars.length > LINK_DISPLAY_MAX
        ? chars.slice(0, LINK_DISPLAY_MAX - 1).join('') + '…'
        : text;
}

// Hide the protocol for display and split the host from the rest so only the
// domain is rendered in bold.
function parseLinkDisplay(display) {
    const withoutProto = String(display || '').replace(/^https?:\/\//i, '');
    const clipped = truncateLinkDisplay(withoutProto);
    const hostEnd = clipped.search(/[/?#]/);
    return {
        domain: hostEnd === -1 ? clipped : clipped.slice(0, hostEnd),
        rest: hostEnd === -1 ? '' : clipped.slice(hostEnd)
    };
}

// Resolve an <a href> into the same shape as a text-derived link.
function resolveHrefLink(href, anchorText = '') {
    const raw = String(href || '').trim();
    if (!raw || raw.startsWith('#')) return null;
    try {
        const resolved = new URL(raw, document.baseURI);
        if (resolved.protocol !== 'http:' && resolved.protocol !== 'https:') return null;
        const urls = extractUrlsFromText(resolved.href);
        return urls.length > 0
            ? {
                ...urls[0],
                fromHref: true,
                hrefText: String(anchorText || '').replace(/\s+/g, ' ').trim()
            }
            : null;
    } catch (e) {
        return null;
    }
}

// Collect anchors intersecting the current selection. cloneContents catches
// fully selected anchors; closest() catches anchors that only contain the
// selection start/end and would otherwise be trimmed away.
function collectHrefLinks() {
    if (!getConfig('enableHiddenLinks')) return [];
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0) return [];

    const range = selection.getRangeAt(0);
    const anchors = new Map();
    const addAnchor = (anchor) => {
        if (!anchor || !anchor.getAttribute) return;
        const href = anchor.getAttribute('href');
        if (!href) return;
        if (!anchors.has(href)) {
            anchors.set(href, String(anchor.textContent || '').replace(/\s+/g, ' ').trim());
        }
    };

    try {
        range.cloneContents().querySelectorAll('a[href]').forEach(addAnchor);
    } catch (e) {}
    [range.startContainer, range.endContainer].forEach((node) => {
        const el = node && (node.nodeType === 1 ? node : node.parentElement);
        if (el && el.closest) addAnchor(el.closest('a[href]'));
    });

    const seen = new Set();
    const links = [];
    anchors.forEach((text, href) => {
        const link = resolveHrefLink(href, text);
        if (link && !seen.has(link.url)) {
            seen.add(link.url);
            links.push(link);
        }
    });
    return links;
}

function mergeHiddenLinks(linkData, hiddenLinks) {
    const urls = linkData && Array.isArray(linkData.urls) ? linkData.urls.slice() : [];
    const seen = new Set(urls.map((url) => url.url));
    hiddenLinks.forEach((link) => {
        if (!link || seen.has(link.url)) return;
        seen.add(link.url);
        urls.push(link);
    });
    if (urls.length === 0) return null;
    return {
        urls,
        password: linkData ? linkData.password : null
    };
}

async function copySingleLink(url) {
    if (await copyToClipboard(url, '')) {
        showToast(t('toast_link_copied'));
    }
}

function formatAllLinks(urls) {
    return urls.map((url) => {
        if (url.fromHref && url.hrefText) {
            return `（${url.hrefText}）${url.url}`;
        }
        return url.url;
    }).join('\n');
}

async function copyAllLinks(urls) {
    const text = formatAllLinks(urls);
    if (await copyToClipboard(text, '')) {
        showToast(t('toast_all_links_copied'));
    }
}

// Long-press copy without affecting the normal click action.
function bindLongPress(btn, onLongPress, duration = 1000) {
    let timer = null;
    const cancel = () => {
        if (timer) {
            clearTimeout(timer);
            timer = null;
        }
    };

    btn.addEventListener('mousedown', (e) => {
        if (e.button !== 0) return;
        btn.__longPressTriggered = false;
        if (uiTimer) {
            clearTimeout(uiTimer);
            uiTimer = null;
        }
        cancel();
        timer = setTimeout(() => {
            timer = null;
            btn.__longPressTriggered = true;
            onLongPress();
        }, duration);
    });
    btn.addEventListener('mouseup', cancel);
    btn.addEventListener('mouseleave', cancel);
    btn.addEventListener('blur', cancel);
}

// Secondary menu for 2-12 links. It always uses the vertical rounded list
// look, even when the toolbar itself is the horizontal capsule.
function showLinkMenu(urls, anchorRect) {
    if (uiTimer) {
        clearTimeout(uiTimer);
        uiTimer = null;
    }
    if (scrollTimeout) {
        clearTimeout(scrollTimeout);
        scrollTimeout = null;
        isScrolling = false;
    }

    shadowRoot.querySelectorAll('.sc-container').forEach((old) => old.remove());

    const menu = document.createElement('div');
    menu.className = 'sc-container sc-link-menu';
    if (getConfig('forceWhiteBlack')) {
        menu.classList.add('theme-light-ui');
    } else {
        menu.classList.add(getBestContrastTheme());
    }

    urls.forEach((url, index) => {
        const item = document.createElement('div');
        item.className = 'sc-link-item';
        item.title = url.url;

        const number = document.createElement('span');
        number.className = 'sc-link-index';
        number.textContent = String(index + 1);
        item.appendChild(number);

        const label = document.createElement('span');
        label.className = 'sc-link-url';
        if (url.fromHref) label.classList.add('sc-link-from-href');
        const { domain, rest } = parseLinkDisplay(url.display || url.url);

        const domainEl = document.createElement('strong');
        domainEl.textContent = domain;
        label.appendChild(domainEl);
        if (rest) label.appendChild(document.createTextNode(rest));
        item.appendChild(label);

        item.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        item.onclick = (e) => {
            if (item.__longPressTriggered) {
                item.__longPressTriggered = false;
                return;
            }
            e.stopPropagation();
            safeOpenTab(url.url, { active: true });
            // Keep the menu open so the user can open more links; the normal
            // timeout starts only after the first item click.
            startLinkMenuTimeout();
        };
        bindLongPress(item, () => copySingleLink(url.url));
        menu.appendChild(item);
    });

    shadowRoot.appendChild(menu);
    menu.style.left = '-9999px';

    requestAnimationFrame(() => {
        const rect = menu.getBoundingClientRect();
        const offset = getConfig('offset');
        let left = anchorRect.left;
        let top = anchorRect.bottom + offset;
        if (top + rect.height > window.innerHeight - 10) {
            top = anchorRect.top - rect.height - offset;
        }
        left = Math.max(10, Math.min(left, window.innerWidth - rect.width - 10));
        top = Math.max(10, Math.min(top, window.innerHeight - rect.height - 10));
        menu.style.left = `${left}px`;
        menu.style.top = `${top}px`;
        menu.classList.add('visible');
    });
}

function startLinkMenuTimeout() {
    if (uiTimer) clearTimeout(uiTimer);
    const timeout = getConfig('timeout');
    if (timeout > 0) {
        uiTimer = setTimeout(hideUI, timeout);
    }
}

function getSearchEngineUrl(engine, query) {
    const template = String(engine.url || '').includes('%s')
        ? engine.url
        : SEARCH_ENGINES.google.url;
    return template.replace('%s', encodeURIComponent(query.trim()));
}

function closeSearchEngineMenu(resetTimer = true) {
    const menu = shadowRoot && shadowRoot.querySelector('.sc-search-menu');
    if (menu) menu.remove();
    if (resetTimer) startLinkMenuTimeout();
}

// The engine picker sits beside the toolbar: right, left, below, then above.
function showSearchEngineMenu(engines, query, anchorRect) {
    if (uiTimer) {
        clearTimeout(uiTimer);
        uiTimer = null;
    }
    const old = shadowRoot.querySelector('.sc-search-menu');
    if (old) old.remove();

    const menu = document.createElement('div');
    menu.className = 'sc-container sc-link-menu sc-search-menu';
    if (getConfig('forceWhiteBlack')) {
        menu.classList.add('theme-light-ui');
    } else {
        menu.classList.add(getBestContrastTheme());
    }

    engines.forEach((engine) => {
        const item = document.createElement('div');
        item.className = 'sc-link-item';
        item.title = engine.url;

        const label = document.createElement('span');
        label.className = 'sc-link-url';
        label.textContent = engine.name;
        item.appendChild(label);

        item.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        item.onclick = (e) => {
            e.stopPropagation();
            safeOpenTab(getSearchEngineUrl(engine, query), { active: true });
            hideUI();
        };
        menu.appendChild(item);
    });

    shadowRoot.appendChild(menu);
    menu.style.left = '-9999px';

    requestAnimationFrame(() => {
        const rect = menu.getBoundingClientRect();
        const gap = getConfig('offset');
        const margin = 10;
        const canRight = anchorRect.right + gap + rect.width <= window.innerWidth - margin;
        const canLeft = anchorRect.left - gap - rect.width >= margin;
        const canBelow = anchorRect.bottom + gap + rect.height <= window.innerHeight - margin;
        const canAbove = anchorRect.top - gap - rect.height >= margin;

        let left;
        let top;
        if (canRight || canLeft) {
            left = canRight
                ? anchorRect.right + gap
                : anchorRect.left - rect.width - gap;
            top = canBelow || !canAbove
                ? anchorRect.top
                : anchorRect.top - rect.height - gap;
        } else if (canBelow || canAbove) {
            left = anchorRect.left;
            top = canBelow
                ? anchorRect.bottom + gap
                : anchorRect.top - rect.height - gap;
        } else {
            left = anchorRect.right + gap;
            top = anchorRect.top;
        }

        left = Math.max(margin, Math.min(left, window.innerWidth - rect.width - margin));
        top = Math.max(margin, Math.min(top, window.innerHeight - rect.height - margin));
        menu.style.left = `${left}px`;
        menu.style.top = `${top}px`;
        menu.classList.add('visible');
    });
}

// Scroll/resize should keep the secondary menu, clamped into the viewport,
// rather than falling back to the selection toolbar.
function repositionLinkMenu() {
    const menu = shadowRoot && shadowRoot.querySelector('.sc-link-menu');
    if (!menu) return false;
    const rect = menu.getBoundingClientRect();
    const left = Math.max(10, Math.min(parseFloat(menu.style.left) || 10, window.innerWidth - rect.width - 10));
    const top = Math.max(10, Math.min(parseFloat(menu.style.top) || 10, window.innerHeight - rect.height - 10));
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    menu.classList.add('visible');
    return true;
}


// Render buttons (supports Copy/Search mode and Paste mode)
function renderButton(rect, mouseX, mouseY, text, html, mode = 'default', targetInput = null, isEditable = false, pasteCache = null, showIdCardCheck = false) {
    // Clean up old button/menu
    shadowRoot.querySelectorAll('.sc-container').forEach((oldBtn) => oldBtn.remove());

    const container = document.createElement('div');
    container.className = 'sc-container';

    // Smart background color detection and theme application
    const forceWB = getConfig('forceWhiteBlack');
    if (forceWB) {
        container.classList.add('theme-light-ui');
    } else {
        const contrastTheme = getBestContrastTheme();
        container.classList.add(contrastTheme);
    }

    const isCol = getConfig('buttonStyle') === 'col';
    container.classList.toggle('sc-col', isCol);

    // Vertical menus show the action name beside the icon; the capsule keeps
    // its icon-only look. The title stays available in both styles.
    const applyButtonLabel = (btn, label, title = label) => {
        btn.title = title;
        if (!isCol) return;
        const span = document.createElement('span');
        span.className = 'sc-btn-label';
        span.textContent = label;
        btn.appendChild(span);
        btn.classList.add('has-label');
    };

    // Pending-lightning-paste preview beside the paste icon.
    const appendPastePreview = (btn, cache) => {
        if (!getConfig('showPastePreview') || !cache) return false;
        if (!cache.text && cache.type !== 'clipboard') return false;

        const span = document.createElement('span');
        span.className = 'sc-btn-label';
        btn.classList.add('has-label');

        // Text copied outside the toolbar cannot be read back; show a generic
        // label instead of pretending we know the clipboard contents.
        if (cache.type === 'clipboard') {
            const strong = document.createElement('strong');
            strong.textContent = isCol
                ? t('paste_clipboard_action')
                : t('paste_clipboard_text');
            span.appendChild(strong);
            btn.appendChild(span);
            return true;
        }

        const isPanCode = cache.type === 'pan_code';
        if (isCol) {
            if (isPanCode) {
                span.appendChild(document.createTextNode(t('btn_pan_code') + ' '));
                const code = document.createElement('strong');
                code.textContent = truncatePasteText(cache.text, 10);
                span.appendChild(code);
            } else {
                const [open, close] = getPasteQuotePair();
                span.textContent = open + truncatePasteText(cache.text, 10) + close;
            }
        } else {
            span.textContent = truncatePasteText(cache.text, 6);
            if (isPanCode) span.classList.add('sc-pan-code');
        }

        btn.appendChild(span);
        return true;
    };

    const applyPasteButtonContent = (btn, cache, title = t('btn_paste')) => {
        if (appendPastePreview(btn, cache)) {
            btn.title = title;
            return;
        }
        applyButtonLabel(btn, t('btn_paste'), title);
    };

    // Mode: Edit mode
    if (isEditMode) {
        // 1. Delete button
        const delBtn = document.createElement('div');
        delBtn.className = 'sc-btn';
        delBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>`;
        applyButtonLabel(delBtn, t('btn_delete'));
        delBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        delBtn.onclick = (e) => {
            e.stopPropagation();
            document.execCommand('delete');
            hideUI();
        };
        container.appendChild(delBtn);

        const div1 = document.createElement('div');
        div1.className = isCol ? 'divider divider-h' : 'divider divider-v';
        container.appendChild(div1);

        // 2. Bold button
        const boldBtn = document.createElement('div');
        boldBtn.className = 'sc-btn';
        boldBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M6 4h8a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path><path d="M6 12h9a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path></svg>`;
        applyButtonLabel(boldBtn, t('btn_bold'));
        boldBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        boldBtn.onclick = (e) => {
            e.stopPropagation();
            document.execCommand('bold');
        };
        container.appendChild(boldBtn);

        const div2 = document.createElement('div');
        div2.className = isCol ? 'divider divider-h' : 'divider divider-v';
        container.appendChild(div2);

        // 3. Highlight button
        const highlightBtn = document.createElement('div');
        highlightBtn.className = 'sc-btn';
        highlightBtn.innerHTML = `<?xml version="1.0" encoding="UTF-8"?><svg width="18" height="18" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6 44L6 25H12V17H36V25H42V44H6Z" fill="none" stroke="#000000" stroke-width="4" stroke-linejoin="bevel"/><path d="M17 17V8L31 4V17" stroke="#000000" stroke-width="4" stroke-linecap="round" stroke-linejoin="bevel"/></svg>`;
        applyButtonLabel(highlightBtn, t('btn_highlight'));
        highlightBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        highlightBtn.onclick = (e) => {
            e.stopPropagation();
            if (!document.execCommand('hiliteColor', false, 'yellow')) {
                document.execCommand('backColor', false, 'yellow');
            }
            hideUI();
        };
        container.appendChild(highlightBtn);
    }
    // Mode A: Default mode
    else if (mode === 'default' || mode === PASTE_MODE_THREE_BTNS) {
        // 1. Copy button
        const copyBtn = document.createElement('div');
        copyBtn.className = 'sc-btn';
        copyBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>`;
        applyButtonLabel(copyBtn, t('btn_copy'));
        copyBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        copyBtn.onclick = async (e) => {
            e.stopPropagation();
            triggerFestivalEffect(e.clientX, e.clientY, shadowRoot);
            const contentToCopy = cachedSelection.text || text;
            const htmlToCopy = cachedSelection.html || html;
            await copyToClipboard(contentToCopy, htmlToCopy);
            if (getConfig('enablePaste')) {
                await safeSetValue('smart_paste_cache', {
                    text: contentToCopy,
                    timestamp: Date.now()
                });
                unregisterVisibilityCleanup();
            }
            showToast(getFestivalToastText());
            setTimeout(hideUI, 50);
        };
        container.appendChild(copyBtn);

        const isInInput = targetInput !== null;

        // 2. Cut button (only show in editable fields)
        if (isInInput && !isEditMode) {
            const div = document.createElement('div');
            div.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(div);

            const cutBtn = document.createElement('div');
            cutBtn.className = 'sc-btn';
            cutBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6" r="3"></circle><circle cx="6" cy="18" r="3"></circle><line x1="20" y1="4" x2="8.12" y2="15.88"></line><line x1="14.47" y1="14.48" x2="20" y2="20"></line><line x1="8.12" y1="8.12" x2="12" y2="12"></line></svg>`;
            applyButtonLabel(cutBtn, t('btn_cut'));
            cutBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
            cutBtn.onclick = async (e) => {
                e.stopPropagation();
                triggerFestivalEffect(e.clientX, e.clientY, shadowRoot);
                const target = targetInput || document.activeElement;
                const contentToCopy = cachedSelection.text || text;
                const htmlToCopy = cachedSelection.html || html;
                const snapshot = captureSelectionSnapshot(target);
                if (await copyToClipboard(contentToCopy, htmlToCopy)) {
                    deleteSelectedText(target, snapshot);
                }
                if (getConfig('enablePaste')) {
                    await safeSetValue('smart_paste_cache', {
                        text: contentToCopy,
                        timestamp: Date.now()
                    });
                    unregisterVisibilityCleanup();
                }
                setTimeout(hideUI, 35);
            };
            container.appendChild(cutBtn);
        }

        // Delete button (always shown inside input fields)
        if (isInInput) {
            const div2 = document.createElement('div');
            div2.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(div2);

            const delBtn = document.createElement('div');
            delBtn.className = 'sc-btn';
            delBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>`;
            applyButtonLabel(delBtn, t('btn_delete'));
            delBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
            delBtn.onclick = (e) => {
                e.stopPropagation();
                const target = targetInput || document.activeElement;
                deleteSelectedText(target, captureSelectionSnapshot(target));
                hideUI();
            };
            container.appendChild(delBtn);
        }
        // Search button (only show outside input fields with short texts)
        else if (!isInInput && !isEditMode && text.trim().length <= 32) {
            const div = document.createElement('div');
            div.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(div);

            const searchBtn = document.createElement('div');
            searchBtn.className = 'sc-btn';
            searchBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>`;
            applyButtonLabel(searchBtn, t('btn_search'));
            searchBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
            searchBtn.onclick = (e) => {
                e.stopPropagation();
                const query = cachedSelection.text || text;

                if (shadowRoot.querySelector('.sc-search-menu')) {
                    closeSearchEngineMenu(true);
                    return;
                }

                const engines = getSearchEngineList();
                if (engines.length > 1) {
                    // Toggle a persistent engine picker beside the toolbar.
                    showSearchEngineMenu(engines, query, container.getBoundingClientRect());
                    return;
                }

                safeOpenTab(getSearchEngineUrl(engines[0], query), { active: true });
                setTimeout(hideUI, 50);
            };
            container.appendChild(searchBtn);
        }

        // Translation has the lowest priority: it comes after copy and search.
        // Skip it when the selection is already in the current language.
        if (getConfig('enableTranslate') !== false && !shouldHideTranslate(text) && typeof requestTranslation === 'function') {
            const translateDiv = document.createElement('div');
            translateDiv.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(translateDiv);

            const translateBtn = document.createElement('div');
            translateBtn.className = 'sc-btn';
            translateBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="m5 8 6 6"></path><path d="m4 14 6-6 2-3"></path><path d="M2 5h12"></path><path d="M7 2h1"></path><path d="m22 22-5-10-5 10"></path><path d="M14 18h6"></path></svg>`;
            applyButtonLabel(translateBtn, t('btn_translate'));
            translateBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
            translateBtn.onclick = (e) => {
                e.stopPropagation();
                const content = cachedSelection.text || text;
                requestTranslation(content, rect);
                setTimeout(hideUI, 50);
            };
            container.appendChild(translateBtn);
        }

        // @ button / chain button logic
        const activeEl = document.activeElement;
        const isUserEditing = activeEl && (
            (['INPUT', 'TEXTAREA'].includes(activeEl.tagName) && !activeEl.readOnly) ||
            activeEl.isContentEditable ||
            document.designMode === 'on'
        );
        if (!isUserEditing && !targetInput && mode !== PASTE_MODE_THREE_BTNS) {
            // 1. Check email first (higher priority than links)
            const emailAddr = extractEmailFromText(text);
            if (emailAddr) {
                const div = document.createElement('div');
                div.className = isCol ? 'divider divider-h' : 'divider divider-v';
                container.appendChild(div);

                const atBtn = document.createElement('div');
                atBtn.className = 'sc-btn';
                atBtn.innerHTML = `<svg viewBox="0 0 48 48" width="18" height="18" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M44 24C44 12.9543 35.0457 4 24 4C12.9543 4 4 12.9543 4 24C4 35.0457 12.9543 44 24 44V44C28.9886 44 33.5507 42.1735 37.0539 39.1529" stroke="currentColor" stroke-width="3" stroke-linecap="butt" stroke-linejoin="miter"/><path d="M24 32C28.4183 32 32 28.4183 32 24C32 19.5817 28.4183 16 24 16C19.5817 16 16 19.5817 16 24C16 28.4183 19.5817 32 24 32Z" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="miter"/><path d="M32 24C32 27.3137 34.6863 30 38 30V30C41.3137 30 44 27.3137 44 24" stroke="currentColor" stroke-width="3" stroke-linecap="butt" stroke-linejoin="miter"/><path d="M32 25V16" stroke="currentColor" stroke-width="3" stroke-linecap="butt" stroke-linejoin="miter"/></svg>`;
                applyButtonLabel(atBtn, t('btn_email'));
                atBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
                atBtn.onclick = async (e) => {
                    e.stopPropagation();
                    // Copy full email to clipboard
                    try {
                        await navigator.clipboard.writeText(emailAddr);
                    } catch (_) {
                        if (typeof GM_setClipboard === 'function') {
                            GM_setClipboard(emailAddr, 'text');
                        }
                    }
                    showToast(t('toast_email_copied'));
                    hideUI();
                };
                container.appendChild(atBtn);
            } else {
                // 2. Detect URLs (supports multiple links)
                // Chinese mode enables cloud drive extraction code; non-Chinese mode extracts plain URLs only
                const isChineseForLink = isChineseUI();
                let linkData = isChineseForLink ? extractLinkAndCode(text) : (() => {
                    const urls = extractUrlsFromText(text);
                    return urls.length > 0 ? { urls, password: null } : null;
                })();
                if (getConfig('enableHiddenLinks')) {
                    linkData = mergeHiddenLinks(linkData, collectHrefLinks());
                }
                if (linkData && linkData.urls && linkData.urls.length > 0 && linkData.urls.length <= LINK_MENU_MAX) {
                    const div = document.createElement('div');
                    div.className = isCol ? 'divider divider-h' : 'divider divider-v';
                    container.appendChild(div);

                    const urlCount = linkData.urls.length;
                    const chainBtn = document.createElement('div');
                    chainBtn.className = 'sc-btn';

                    // Icon wrapper (18x18, serves as badge positioning anchor)
                    const iconWrap = document.createElement('span');
                    iconWrap.className = 'sc-icon-wrap';
                    iconWrap.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>`;
                    chainBtn.appendChild(iconWrap);

                    // Badge: single link + extraction code → key icon; multiple links → number badge
                    const isSingleLink = urlCount === 1;
                    if (isChineseForLink && isSingleLink && linkData.password) {
                        const badge = document.createElement('span');
                        badge.className = 'sc-badge sc-badge-key';
                        badge.innerHTML = `<svg viewBox="0 0 48 48" width="10" height="10" stroke="currentColor" fill="none"><path d="M22.8682 24.2982C25.4105 26.7935 26.4138 30.4526 25.4971 33.8863C24.5805 37.32 21.8844 40.0019 18.4325 40.9137C14.9806 41.8256 11.3022 40.8276 8.79375 38.2986C5.02208 34.4141 5.07602 28.2394 8.91499 24.4206C12.754 20.6019 18.9613 20.5482 22.8664 24.3L22.8682 24.2982Z"/><path d="M23 24L40 7"/><path d="M30.3052 16.9001L35.7337 22.3001L42.0671 16.0001L36.6385 10.6001L30.3052 16.9001Z"/></svg>`;
                        iconWrap.appendChild(badge);
                    } else if (urlCount > 1) {
                        const badge = document.createElement('span');
                        badge.className = 'sc-badge';
                        badge.textContent = urlCount;
                        iconWrap.appendChild(badge);
                    }

                    const titlePrefix = urlCount > 1 ? ('(' + urlCount + ') ') : '';
                    applyButtonLabel(chainBtn, t('btn_open_link'), titlePrefix + t('btn_open_link'));
                    chainBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
                    chainBtn.onclick = async (e) => {
                        if (chainBtn.__longPressTriggered) {
                            chainBtn.__longPressTriggered = false;
                            return;
                        }
                        e.stopPropagation();
                        // Single link + Chinese mode: write extraction code to lightning paste cache
                        if (isSingleLink && isChineseForLink && getConfig('enablePaste') && linkData.password) {
                            await safeSetValue('smart_paste_cache', {
                                text: linkData.password,
                                timestamp: Date.now() + 22000,
                                type: 'pan_code'
                            });
                            unregisterVisibilityCleanup();
                            showToast(t('toast_password_pasted'));
                        }

                        if (isSingleLink) {
                            safeOpenTab(linkData.urls[0].url, { active: true });
                            hideUI();
                            return;
                        }

                        // 2-12 links: replace the toolbar with a numbered menu.
                        const anchorRect = container.getBoundingClientRect();
                        showLinkMenu(linkData.urls, anchorRect);
                    };
                    bindLongPress(chainBtn, () => {
                        if (isSingleLink) copySingleLink(linkData.urls[0].url);
                        else copyAllLinks(linkData.urls);
                    });
                    container.appendChild(chainBtn);
                }
            }
        }

        // Check if "correct" button should be shown
        const isChineseEnv = isChineseUI();
        if (isChineseEnv && targetInput) {
            const isInputType = targetInput.tagName === 'INPUT';
            if (smartCorrectText(text, isInputType) !== null) {
                const div = document.createElement('div');
                div.className = isCol ? 'divider divider-h' : 'divider divider-v';
                container.appendChild(div);

                const correctBtn = document.createElement('div');
                correctBtn.className = 'sc-btn';
                correctBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><path d="M9 15l2 2 4-4"></path></svg>`;
                applyButtonLabel(correctBtn, "Correct");
                correctBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
                correctBtn.onclick = (e) => {
                    e.stopPropagation();
                    handleTextCorrection(targetInput, text);
                };
                container.appendChild(correctBtn);
            }
        }

        // 3. Append paste button in three-button lightning paste mode
        if (mode === PASTE_MODE_THREE_BTNS) {
            const div = document.createElement('div');
            div.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(div);
            const pasteBtn = document.createElement('div');
            pasteBtn.className = 'sc-btn';
            pasteBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>`;
            applyPasteButtonContent(pasteBtn, pasteCache);
            pasteBtn.onmousedown = e => { e.preventDefault(); e.stopPropagation(); };
            pasteBtn.onclick = async (e) => {
                e.stopPropagation();
                const cache = await safeGetValue('smart_paste_cache', null);
                if (cache && (cache.text || cache.type === 'clipboard')) {
                    if (cache.type === 'clipboard') {
                        await performClipboardPaste(document.activeElement, cache);
                    } else {
                        performPaste(document.activeElement, cache.text, {
                            panCode: cache.type === 'pan_code'
                        });
                        // Reset timestamp after paste to allow repeated use on same page
                        await safeSetValue('smart_paste_cache', {
                            text: cache.text,
                            timestamp: Date.now()
                        });
                        registerVisibilityCleanup();
                    }
                }
                hideUI();
            };
            container.appendChild(pasteBtn);
        }
    }
    // Mode C: input whitespace selection (delete + optional paste)
    else if (mode === PASTE_MODE_WHITESPACE) {
        const delBtn = document.createElement('div');
        delBtn.className = 'sc-btn';
        delBtn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>`;
        applyButtonLabel(delBtn, t('btn_delete'));
        delBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        delBtn.onclick = (e) => {
            e.stopPropagation();
            const target = targetInput || document.activeElement;
            const start = target.selectionStart;
            const end = target.selectionEnd;
            if (typeof start !== 'number' || typeof end !== 'number' || start === end) {
                hideUI();
                return;
            }
            if (target.value.substring(start, end).trim() !== '') {
                hideUI();
                return;
            }

            if (end - start >= 2) {
                // Collapse the whitespace run to one space and keep the delete
                // button selected so another click removes it.
                replaceInputRange(target, start, end, ' ', true);
            } else {
                replaceInputRange(target, start, end, '', false);
                hideUI();
            }
        };
        container.appendChild(delBtn);

        if (pasteCache && (pasteCache.text || pasteCache.type === 'clipboard')) {
            const div = document.createElement('div');
            div.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(div);

            const pasteBtn = document.createElement('div');
            pasteBtn.className = 'sc-btn';
            pasteBtn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>';
            applyPasteButtonContent(pasteBtn, pasteCache);
            pasteBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
            pasteBtn.onclick = async (e) => {
                e.stopPropagation();
                if (pasteCache.type === 'clipboard') {
                    await performClipboardPaste(targetInput || document.activeElement, pasteCache);
                } else {
                    performPaste(targetInput, pasteCache.text, {
                        panCode: pasteCache.type === 'pan_code'
                    });
                }
                hideUI();
            };
            container.appendChild(pasteBtn);
        }
    }
    // Mode B: Paste mode (lightning paste / cloud drive extraction code)
    else if (mode === 'paste') {
        const isPanCode = pasteCache && pasteCache.type === 'pan_code';
        const pasteTitle = isPanCode
            ? t('btn_paste') + ' ' + (pasteCache.text || '')
            : t('btn_paste');
        const pasteBtn = document.createElement('div');
        pasteBtn.className = 'sc-btn';
        if (isPanCode) {
            // Key icon (for cloud drive extraction code)
            pasteBtn.innerHTML = '<svg viewBox="0 0 48 48" width="18" height="18" stroke="currentColor" stroke-width="3" fill="none"><path d="M22.8682 24.2982C25.4105 26.7935 26.4138 30.4526 25.4971 33.8863C24.5805 37.32 21.8844 40.0019 18.4325 40.9137C14.9806 41.8256 11.3022 40.8276 8.79375 38.2986C5.02208 34.4141 5.07602 28.2394 8.91499 24.4206C12.754 20.6019 18.9613 20.5482 22.8664 24.3L22.8682 24.2982Z"/><path d="M23 24L40 7"/><path d="M30.3052 16.9001L35.7337 22.3001L42.0671 16.0001L36.6385 10.6001L30.3052 16.9001Z"/></svg>';
        } else {
            pasteBtn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>';
        }
        applyPasteButtonContent(pasteBtn, pasteCache, pasteTitle);
        pasteBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        pasteBtn.onclick = async (e) => {
            e.stopPropagation();
            if (pasteCache && pasteCache.type === 'clipboard') {
                await performClipboardPaste(targetInput || document.activeElement, pasteCache);
                hideUI();
                return;
            }
            if (isPanCode) {
                performPaste(targetInput || document.activeElement, pasteCache.text, { panCode: true });
                await safeSetValue('smart_paste_cache', { text: '', timestamp: 0 });
                unregisterVisibilityCleanup();
                hideUI();
                return;
            }
            performPaste(targetInput, text);
            // Reset timestamp after paste to allow repeated use on same page
            // Note: caching target input content here, not clipboard content; reset only in direct paste mode
            const existingCache = await safeGetValue('smart_paste_cache', null);
            if (existingCache && existingCache.text) {
                await safeSetValue('smart_paste_cache', {
                    text: existingCache.text,
                    timestamp: Date.now()
                });
                registerVisibilityCleanup();
            }
            hideUI();
        };
        container.appendChild(pasteBtn);
    }

    // The ID card action is appended to whichever toolbar the selection
    // already produced (paste actions, default copy/cut tools, ...), never a
    // standalone replacement for them.
    if (showIdCardCheck) {
        if (container.children.length > 0) {
            const divider = document.createElement('div');
            divider.className = isCol ? 'divider divider-h' : 'divider divider-v';
            container.appendChild(divider);
        }

        const idBtn = document.createElement('div');
        idBtn.className = 'sc-btn';
        idBtn.innerHTML = `<svg viewBox="0 0 48 48" width="18" height="18" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="4" y="8" width="40" height="32" rx="2" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/><path d="M17 25C19.2091 25 21 23.2091 21 21C21 18.7909 19.2091 17 17 17C14.7909 17 13 18.7909 13 21C13 23.2091 14.7909 25 17 25Z" fill="none" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/><path d="M23 31C23 27.6863 20.3137 25 17 25C13.6863 25 11 27.6863 11 31" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M28 20H36" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M30 28H36" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
        applyButtonLabel(idBtn, '身份证号码校验');
        idBtn.onmousedown = (e) => { e.preventDefault(); e.stopPropagation(); };
        idBtn.onclick = (e) => {
            e.stopPropagation();
            showToast(getIdCardCheckMessage(text));
        };
        container.appendChild(idBtn);
    }
    container.setAttribute('data-btn-count', container.children.length);

    shadowRoot.appendChild(container);

    // Calculate position (common logic)
    container.style.left = '-9999px';

    requestAnimationFrame(() => {
        const btnRect = container.getBoundingClientRect();
        const btnW = btnRect.width;
        const btnH = btnRect.height;
        const offset = getConfig('offset');
        const viewportW = window.innerWidth;
        const viewportH = window.innerHeight;

        let targetX, targetY;

        if (rect) {
            const isBackward = rect.isBackward || false;
            const isVertical = rect.isVertical || false;
            if (isVertical) {
                if (isBackward) {
                    targetX = rect.right + offset;
                    targetY = rect.top;
                } else {
                    targetX = rect.left - btnW - offset;
                    targetY = rect.bottom - btnH;
                }
            } else {
                if (isBackward) {
                    targetX = rect.left - (btnW / 2);
                    targetY = rect.top - btnH - offset;
                } else {
                    targetX = rect.right - (btnW / 2);
                    const spaceBelow = viewportH - rect.bottom;
                    if (spaceBelow < (btnH + offset + 20)) {
                        targetY = rect.top - btnH - offset;
                    } else {
                        targetY = rect.bottom + offset;
                    }
                }
            }
        } else {
            if (mouseY > viewportH / 2) {
                targetY = mouseY - btnH - offset;
            } else {
                targetY = mouseY + offset;
            }
            if (mouseX > viewportW / 2) {
                targetX = mouseX - btnW - offset;
            } else {
                targetX = mouseX + offset;
            }
        }

        // Edge detection
        const margin = 10;
        targetX = Math.max(margin, Math.min(targetX, viewportW - btnW - margin));
        targetY = Math.max(margin, Math.min(targetY, viewportH - btnH - margin));

        container.style.left = `${targetX}px`;
        container.style.top = `${targetY}px`;
        container.classList.add('visible');

        const timeout = getConfig('timeout');
        if (timeout > 0) {
            if (uiTimer) clearTimeout(uiTimer);
            uiTimer = setTimeout(hideUI, timeout);
        }
    });
}

function hideUI() {
    const containers = shadowRoot ? shadowRoot.querySelectorAll('.sc-container') : [];
    containers.forEach((btn) => {
        btn.classList.remove('visible');
        setTimeout(() => {
            if (btn && btn.parentNode) btn.remove();
        }, 200);
    });
    cachedSelection = { text: '', html: '' };
    clearSelectionScrollTargets();
    lastSelectionRoot = null;
}


// ---- 14-events.js ----
// Module 14: Event Handlers

// Trim whitespace at both ends of a normal page selection before the toolbar
// is shown. Returns false when the selection contains only whitespace.
function trimRangeWhitespace(selection) {
    try {
        const range = selection.getRangeAt(0);
        const root = range.commonAncestorContainer.nodeType === 1
            ? range.commonAncestorContainer
            : range.commonAncestorContainer.parentNode;
        if (!root) return false;

        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
        const chars = [];
        let node;
        while ((node = walker.nextNode())) {
            if (!range.intersectsNode(node)) continue;
            const data = node.data;
            const start = node === range.startContainer ? range.startOffset : 0;
            const end = node === range.endContainer ? range.endOffset : data.length;
            for (let i = start; i < end; i++) {
                chars.push({ node, offset: i, char: data[i] });
            }
        }

        let first = 0;
        let last = chars.length - 1;
        while (first <= last && /\s/.test(chars[first].char)) first++;
        while (last >= first && /\s/.test(chars[last].char)) last--;
        if (first > last) return false;

        range.setStart(chars[first].node, chars[first].offset);
        range.setEnd(chars[last].node, chars[last].offset + 1);
        selection.removeAllRanges();
        selection.addRange(range);
        return true;
    } catch (e) {
        return false;
    }
}

// Selection root and scroll-target tracking. Sites such as Bilibili render
// comments inside open shadow roots, where window.getSelection() is empty; the
// ShadowRoot owns its own Selection object in Chromium.
let lastSelectionRoot = null;
let selectionScrollTargets = [];

function selectionOwnedByRoot(selection, root) {
    try {
        const range = selection.getRangeAt(0);
        // Ancestor shadow roots expose a shadow-including range whose start is
        // the fragment itself; it stringifies fine but cannot be trimmed or
        // measured. Only accept a range anchored in a real node of this root.
        if (range.startContainer.nodeType === 11) return false;
        return range.startContainer.getRootNode() === root;
    } catch (e) {
        return false;
    }
}

// The mouseup target is not necessarily inside the shadow root that owns the
// selection: a full-line drag often releases on the host or its padding.
// Ancestor roots expose a shadow-including selection too, so prefer the
// deepest root that owns a usable range.
function findShadowSelection(start) {
    if (!start) return null;
    const queue = [{ node: start, depth: 0 }];
    const seen = new Set();
    let best = null;
    while (queue.length) {
        const { node, depth } = queue.shift();
        if (!node || seen.has(node)) continue;
        seen.add(node);
        if (node.nodeType === 1) {
            if (node.shadowRoot) {
                const selection = typeof node.shadowRoot.getSelection === 'function'
                    ? node.shadowRoot.getSelection()
                    : null;
                if (selection && selection.rangeCount > 0 && selectionOwnedByRoot(selection, node.shadowRoot)) {
                    if (!best || depth + 1 > best.depth) {
                        best = { selection, root: node.shadowRoot, depth: depth + 1 };
                    }
                }
                queue.push({ node: node.shadowRoot, depth: depth + 1 });
            }
            for (const child of node.children) {
                queue.push({ node: child, depth: depth + 1 });
            }
        } else if (node.nodeType === 11) {
            for (const child of node.children) {
                queue.push({ node: child, depth: depth + 1 });
            }
        }
    }
    return best ? { selection: best.selection, root: best.root } : null;
}

function getSelectionFromEvent(event) {
    const path = event?.composedPath?.() || [];

    // Plain light-DOM selections need no shadow scan; keep the common path cheap.
    const pathHasShadow = path.some((node) => {
        if (!node) return false;
        if (node.shadowRoot) return true;
        const root = node.getRootNode?.();
        return Boolean(root && root.host);
    });
    if (!pathHasShadow) {
        return { selection: window.getSelection(), root: document };
    }

    // Prefer the innermost open shadow root that actually owns the range. The
    // mouseup target can be an outer host, so walking only its path roots can
    // pick an ancestor selection object instead of the real nested one.
    // composedPath()[0] keeps the real inner target even when event.target is
    // retargeted to the outermost host.
    const target = path[0] || event?.target;
    const targetRoot = target?.getRootNode?.();
    const start = targetRoot?.host || target;
    const found = findShadowSelection(start);
    if (found) return found;

    const seenRoots = new Set();
    for (const node of path) {
        // Prefer the node's own shadow root before its parent root; a host node
        // belongs to the outer tree but owns the nested selection.
        const roots = [node?.shadowRoot, node?.getRootNode?.()].filter(Boolean);
        for (const root of roots) {
            if (root === document || !root.host || seenRoots.has(root)) continue;
            seenRoots.add(root);
            if (typeof root.getSelection !== 'function') continue;
            const selection = root.getSelection();
            if (selection && selection.rangeCount > 0 && selectionOwnedByRoot(selection, root)) {
                return { selection, root };
            }
        }
    }

    const pageFound = findShadowSelection(document.documentElement);
    if (pageFound) return pageFound;

    return { selection: window.getSelection(), root: document };
}

function getSelectionForRoot(root) {
    if (root && root !== document && typeof root.getSelection === 'function') {
        try {
            const selection = root.getSelection();
            if (selection && selection.rangeCount > 0) return selection;
        } catch (e) {}
    }
    return window.getSelection();
}

function getActiveSelection() {
    if (lastSelectionRoot && lastSelectionRoot !== document) {
        const selection = getSelectionForRoot(lastSelectionRoot);
        if (selection && selection.rangeCount > 0) return selection;
    }
    return window.getSelection();
}

function clearSelectionScrollTargets() {
    selectionScrollTargets.forEach((target) => {
        target.removeEventListener('scroll', handleResizeOrScroll, { passive: true });
    });
    selectionScrollTargets = [];
}

// Scroll events do not bubble (and may not cross shadow boundaries), so bind
// them to the actual scrollable ancestors of the current selection.
function bindSelectionScrollTargets(selection) {
    clearSelectionScrollTargets();
    if (!selection || selection.rangeCount === 0) return;

    let node = selection.getRangeAt(0).commonAncestorContainer;
    const seen = new Set();
    while (node) {
        const el = node.nodeType === 1 ? node : node.parentElement;
        if (!el) break;
        if (!seen.has(el)) {
            seen.add(el);
            if (el.scrollHeight > el.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1) {
                el.addEventListener('scroll', handleResizeOrScroll, { passive: true });
                selectionScrollTargets.push(el);
            }
        }
        node = el.parentNode || el.host;
    }
}

function handleSelectionMouseUp(e) {
    if (hostElement && e.composedPath().includes(hostElement)) return;
    if (!hostElement) initContainer();
    if (isScrolling) return;

    // Resolve the selection while the event path is still alive. Deferring this
    // to the setTimeout below loses composedPath(), and some sites also clear
    // the selection on mouseup before the timer runs.
    const { selection, root: selectionRoot } = getSelectionFromEvent(e);
    if (!selection || selection.rangeCount === 0) {
        lastSelectionRoot = null;
        clearSelectionScrollTargets();
        hideUI();
        return;
    }
    lastSelectionRoot = selectionRoot;

    const target = document.activeElement;
    const isTextInput = target && (
        (['INPUT', 'TEXTAREA'].includes(target.tagName) && !target.disabled && !target.readOnly)
    );
    const isEditable = isTextInput || Boolean(target && target.isContentEditable);

    // Page selections trim edge whitespace; editable selections keep it.
    if (!isEditable && !trimRangeWhitespace(selection)) {
        hideUI();
        return;
    }

    const text = selection.toString();
    if (!text) {
        hideUI();
        return;
    }
    if (!isEditable && text.trim().length === 0) {
        hideUI();
        return;
    }
    // Whitespace-only input/textarea selection is handled by the capture
    // mouseup handler, which expands it and builds the delete/paste UI.
    if (isTextInput && text.trim().length === 0) return;

    const range = selection.getRangeAt(0);
    const container = document.createElement('div');
    container.appendChild(range.cloneContents());
    const html = container.innerHTML;
    cachedSelection = { text, html };

    // Snapshot geometry before any page handler can mutate the range.
    const rect = getSmartSelectionState(selection);
    bindSelectionScrollTargets(selection);
    initContainer();

    const releaseX = e.clientX;
    const releaseY = e.clientY;
    setTimeout(async () => {
        let cache = null;
        if (getConfig('enablePaste')) {
            cache = await safeGetValue('smart_paste_cache', null);
        }
        const isChineseEnv = isChineseUI();
        const cacheValid = cache && cache.text && (Date.now() - cache.timestamp < getPasteTtlMs()) && !(isChineseEnv && cache.type === 'pan_code');
        const isInput = isEditable;
        const mode = (cacheValid && isInput) ? PASTE_MODE_THREE_BTNS : 'default';
        renderButton(rect, releaseX, releaseY, text, html || '', mode, isInput ? target : null, isInput, cache);
    }, 10);
}

function handleGlobalMouseDown(e) {
    if (hostElement && e.composedPath().includes(hostElement)) {
        // Clicked inside button, keep it
    } else {
        shadowRoot?.querySelectorAll('.sc-container').forEach((btn) => {
            btn.classList.remove('visible');
        });
    }
}

// Scroll and resize handler
const handleResizeOrScroll = () => {
    if (!hostElement) return;
    const mode = getConfig('scrollRepaintMode');
    const btn = shadowRoot.querySelector('.sc-container');
    if (!btn) return;

    // The search engine picker is a persistent companion of the toolbar.
    if (shadowRoot.querySelector('.sc-search-menu')) {
        if (mode === SCROLL_REPAINT_MODE.HIDE) {
            hideUI();
            return;
        }
        return;
    }

    // The multi-link picker is still the active surface; repaint/keep it
    // instead of falling back to a fresh selection toolbar.
    if (btn.classList.contains('sc-link-menu')) {
        if (mode === SCROLL_REPAINT_MODE.HIDE) {
            hideUI();
            return;
        }
        repositionLinkMenu();
        return;
    }

    if (mode === SCROLL_REPAINT_MODE.HIDE) {
        hideUI();
        return;
    }

    if (mode === SCROLL_REPAINT_MODE.VIEWPORT) {
        const selection = getActiveSelection();
        if (!selection.rangeCount) { hideUI(); return; }
        const rect = selection.getRangeAt(0).getBoundingClientRect();
        const inViewport = rect.top >= 0 && rect.left >= 0 &&
            rect.bottom <= window.innerHeight &&
            rect.right <= window.innerWidth;
        if (!inViewport) { hideUI(); return; }
    }

    btn.classList.remove('visible');
    isScrolling = true;
    if (scrollTimeout) clearTimeout(scrollTimeout);
    scrollTimeout = setTimeout(() => {
        isScrolling = false;
        const selection = getActiveSelection();
        if (selection && selection.toString().trim().length > 0) {
            const rect = getSmartSelectionState(selection);
            if (rect) {
                renderButton(rect, rect.right, rect.top,
                    selection.toString(),
                    cachedSelection.html);
            }
        }
    }, 300);
};

function handleContextMenu(e) {
    hideUI();
    if (getConfig('enablePaste')) {
        safeSetValue('smart_paste_cache', { text: '', timestamp: 0 });
        unregisterVisibilityCleanup();
    }
}

function handleKeydownHideUI(e) {
    if (isUnlockMode) return;
    hideUI();
}

// A normal Ctrl+C / context-menu copy outside the toolbar. Capture the text
// synchronously from the selection and share it through the existing cache so
// another tab can offer lightning paste without polling or clipboard reads.
async function handleExternalCopy(e) {
    if (!getConfig('enablePaste')) return;

    let text = '';
    const target = e.target;
    if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) {
        const start = target.selectionStart;
        const end = target.selectionEnd;
        if (typeof start === 'number' && typeof end === 'number' && start !== end) {
            text = target.value.substring(start, end);
        }
    }
    if (!text) {
        const sel = getSelectionFromEvent(e).selection;
        text = sel ? sel.toString() : '';
    }
    if (!text) return;

    unregisterVisibilityCleanup();
    await safeSetValue('smart_paste_cache', {
        text,
        timestamp: Date.now(),
        type: 'clipboard'
    });
}

// Input paste mouseup handler
function handleInputPasteMouseUp(e) {
    const target = e.target;
    const isInput = (['INPUT', 'TEXTAREA'].includes(target.tagName) && !target.disabled && !target.readOnly) || target.isContentEditable;
    if (!isInput) return;
    setTimeout(async () => {
        let selectedText = '';
        let hasSelection = false;
        let whitespaceSelection = false;

        if (['INPUT', 'TEXTAREA'].includes(target.tagName)) {
            let start = target.selectionStart;
            let end = target.selectionEnd;
            if (typeof start === 'number' && typeof end === 'number' && start !== end) {
                selectedText = target.value.substring(start, end);
                hasSelection = true;
                if (selectedText.trim() === '') {
                    // Expand a all-whitespace selection across adjacent
                    // whitespace the user did not select.
                    const isSpace = (index) => index >= 0
                        && index < target.value.length
                        && /\s/.test(target.value[index]);
                    while (start > 0 && isSpace(start - 1)) start--;
                    while (end < target.value.length && isSpace(end)) end++;
                    if (start !== target.selectionStart || end !== target.selectionEnd) {
                        target.setSelectionRange(start, end);
                    }
                    selectedText = target.value.substring(start, end);
                    whitespaceSelection = true;
                }
            }
        } else if (target.isContentEditable) {
            const sel = getSelectionFromEvent(e).selection;
            if (sel && sel.rangeCount > 0 && !sel.isCollapsed) {
                selectedText = sel.toString();
                hasSelection = true;
            }
        }

        let cache = null;
        if (getConfig('enablePaste')) {
            cache = await safeGetValue('smart_paste_cache', null);
            if (cache && (!cache.text && cache.type !== 'clipboard')) cache = null;
            if (cache && Date.now() - cache.timestamp > getPasteTtlMs()) cache = null;
        }

        // The ID card action is appended to the normal input toolbar when the
        // selection looks like a mainland ID number (Chinese UI only).
        const showIdCardCheck = isInput && isChineseUI() && isIdCardCandidate(selectedText);
        if (showIdCardCheck) rememberIdCardDragGuard(target, selectedText);

        if (whitespaceSelection) {
            initContainer();
            // An <input>/<textarea> has no DOM Range, so there is no caret rect
            // to anchor to. Passing the element rect pinned the button to the
            // input's right edge; a null rect makes renderButton fall back to
            // the mouse-release point, i.e. the end of the whitespace run.
            renderButton(
                null,
                e.clientX,
                e.clientY,
                selectedText,
                '',
                PASTE_MODE_WHITESPACE,
                target,
                false,
                cache
            );
            return;
        }

        if (!cache) {
            if (!showIdCardCheck) return;
            initContainer();
            renderButton(null, e.clientX, e.clientY, selectedText, '', 'default', target, false, null, true);
            return;
        }

        // Cloud drive extraction code cache (Chinese mode only): force single paste button (key icon)
        const isChineseEnv = isChineseUI();
        if (isChineseEnv && cache.type === 'pan_code') {
            initContainer();
            const rect = target.getBoundingClientRect();
            renderButton(rect, e.clientX, e.clientY, cache.text, '', 'paste', target, false, cache);
            return;
        }

        const isReplaceIntent = selectedText === ' ' || selectedText === '，';
        const mode = (hasSelection && !isReplaceIntent) ? PASTE_MODE_THREE_BTNS : 'paste';
        const textArg = (mode === 'paste') ? cache.text : selectedText;

        const rect = (target.isContentEditable && hasSelection)
            ? getSmartSelectionState(getSelectionFromEvent(e).selection)
            : null;
        if (!hostElement) initContainer();
        renderButton(rect, e.clientX, e.clientY, textArg, '', mode, target, false, cache, showIdCardCheck);
    }, 20);
}


// ---- 15-text-correct.js ----
// Module 15: Smart Text Correction

// Core correction algorithm with 9 Chinese typography rules
function smartCorrectText(text, isInputType) {
    // 0. Basic determination
    const hasHanzi = /[\u4e00-\u9fa5]/.test(text);
    const hasCNPunct = /[，。：；？！""''（）【】《》]/.test(text);
    const hasNum = /\d/.test(text);

    let activeRules = {
        basic: hasHanzi,
        punct: hasHanzi || hasCNPunct,
        unit: hasHanzi || hasCNPunct || hasNum,
        pureCN: hasHanzi && !/[a-zA-Z]/.test(text.replace(/[a-zA-Z]+(?=[%℃$])/, ''))
    };

    if (!activeRules.basic && !activeRules.punct && !activeRules.unit) return null;

    const applyRule = (txt, regex, replacement) => {
        const parts = txt.split(/(".*?"|".*?")/g);
        return parts.map((part, i) => {
            if (i % 2 === 1) return part;
            return part.replace(regex, replacement);
        }).join('');
    };

    let result = text;

    // --- Rule 9: Line break / whitespace removal (highest priority) ---
    if (activeRules.basic) {
        const rule9Regex = /([\u4e00-\u9fa5。])(\s{2,})(?=[\u4e00-\u9fa5]|\d{1,3}(?:[、.]|\s))/g;
        result = applyRule(result, rule9Regex, (match, p1, p2) => {
            return p1 + (isInputType ? '' : '\n');
        });
    }

    // --- Rule 6: English punctuation to Chinese in pure Chinese environment ---
    if (activeRules.pureCN) {
        const parts = result.split(/(".*?"|".*?")/g);
        result = parts.map((part, i) => {
            if (i % 2 === 1) return part;
            let p = part;
            p = p.replace(/\.{3,}/g, '……');
            p = p.replace(/\.{2}/g, '。');
            p = p.replace(/(?<!\d)\.(?!\d)|(?<=\d)\.(?!\d)|(?<!\d)\.(?=\d)/g, '。');
            const map = {',':'，', '?':'？', '!':'！', ':':'：', ';':'；', '(':'（', ')':'）'};
            p = p.replace(/[,?!:;()]/g, m => map[m]);
            return p;
        }).join('');
    }

    // --- Rule 1: Add space between Chinese and English ---
    if (activeRules.basic) {
        result = applyRule(result, /([\u4e00-\u9fa5])([a-zA-Z])/g, '$1 $2');
        result = applyRule(result, /([a-zA-Z])([\u4e00-\u9fa5])/g, '$1 $2');
    }

    // --- Rule 2: Add space between Chinese and numbers (including operators) ---
    if (activeRules.basic) {
        const isMathContext = /[+*/=]|等于/.test(text);
        const charSet = isMathContext ? '[\\d+\\-*/=]' : '[\\d]';
        const regex1 = new RegExp(`([\\u4e00-\\u9fa5])(?=${charSet})`, 'g');
        const regex2 = new RegExp(`(${charSet})(?=[\\u4e00-\\u9fa5])`, 'g');
        result = applyRule(result, regex1, '$1 ');
        result = applyRule(result, regex2, '$1 ');
    }

    // --- Rule 3: Remove space between char/number and trailing punctuation ---
    if (activeRules.punct) {
        result = applyRule(result, /([a-zA-Z0-9\u4e00-\u9fa5])\s+([,.:;?!，。：；？！、\])}（）】【《》[({""''"'])/g, '$1$2');
    }

    // --- Rule 4: Number/char and unit (%, ℃, $) ---
    if (activeRules.unit) {
        result = applyRule(result, /(\d)\s+([%℃$])/g, '$1$2');
        result = applyRule(result, /([^\s\d])([%℃$])/g, '$1 $2');
    }

    // --- Rule 5: Deduplicate Chinese periods ---
    if (activeRules.basic) {
        const parts = result.split(/(".*?"|".*?")/g);
        result = parts.map((part, i) => {
            if (i % 2 === 1) return part;
            part = part.replace(/。{3,8}/g, '……');
            part = part.replace(/。{2}/g, '。');
            return part;
        }).join('');
    }

    // --- Rule 7: Chinese colon between numbers to English colon ---
    if (activeRules.unit) {
        result = applyRule(result, /(\d)\s*：\s*(\d)/g, '$1:$2');
    }

    // --- Rule 8: Fix double quotes (only when exactly one pair) ---
    if (activeRules.punct) {
        const quoteCount = (result.match(/[""]/g) || []).length;
        if (quoteCount === 2) {
            let qIndex = 0;
            result = result.replace(/[""]/g, () => {
                qIndex++;
                return qIndex === 1 ? '\u201C' : '\u201D';
            });
        }
    }

    return result === text ? null : result;
}

// Execute correction operation
async function handleTextCorrection(target, originalText) {
    const isInput = target.tagName === 'INPUT';
    const newText = smartCorrectText(originalText, isInput);

    if (!newText) {
        showToast('No correction needed');
        return;
    }

    if (document.execCommand && typeof document.execCommand === 'function') {
        try {
            target.focus();
            document.execCommand('insertText', false, newText);
        } catch (e) {
            performPaste(target, newText);
        }
    } else {
        performPaste(target, newText);
    }

    showToast('Text corrected');
    hideUI();
}

// Build the clipboard payload used by the synthetic paste event. DataTransfer
// is preferred; the plain object keeps pages working in restricted sandboxes.
function createPasteData(text) {
    try {
        if (typeof DataTransfer === 'function') {
            const data = new DataTransfer();
            data.setData('text/plain', text);
            return data;
        }
    } catch (e) {}
    return {
        types: ['text/plain'],
        getData: (type) => (type === 'text/plain' ? text : '')
    };
}

// A native-like paste event is what controlled editors (Baidu Translate,
// Vditor, ProseMirror, ...) listen to in order to update their own model.
// execCommand('insertText') only mutates the DOM and can leave that model empty.
function dispatchPasteEvent(target, text) {
    const data = createPasteData(text);
    let event;
    try {
        event = new ClipboardEvent('paste', {
            bubbles: true,
            cancelable: true,
            clipboardData: data
        });
    } catch (e) {
        event = new Event('paste', { bubbles: true, cancelable: true });
    }
    if (!event.clipboardData) {
        try {
            Object.defineProperty(event, 'clipboardData', { value: data });
        } catch (e) {}
    }
    target.dispatchEvent(event);
    return event.defaultPrevented;
}

// Paste feedback. With previews enabled, include up to 10 characters of the
// pasted text (quoted in the UI language); pan codes stay bold.
function showPasteResultToast(text, panCode, compat = false, externalClipboard = false) {
    if (externalClipboard) {
        if (getConfig('showPastePreview')) {
            showToast(t('toast_clipboard_pasted'));
        } else {
            showToast(t('toast_pasted'));
        }
        return;
    }

    if (!getConfig('showPastePreview')) {
        showToast(
            compat
                ? t('toast_paste_compat')
                : panCode
                    ? t('toast_password_pasted')
                    : t('toast_pasted')
        );
        return;
    }

    if (panCode) {
        const fragment = document.createDocumentFragment();
        fragment.appendChild(document.createTextNode(t('toast_password_pasted') + ' '));
        const code = document.createElement('strong');
        code.textContent = truncatePasteText(text, 10);
        fragment.appendChild(code);
        showToast(fragment);
        return;
    }

    const [open, close] = getPasteQuotePair();
    const base = compat ? t('toast_paste_compat') : t('toast_pasted');
    const separator = baseLanguageTag(getCurrentLanguage()) === 'zh' ? '' : ' ';
    showToast(`${base}${separator}${open}${truncatePasteText(text, 10)}${close}`);
}

// Paste text copied outside the toolbar. If the copy event captured the text,
// use it; otherwise ask the Clipboard API or the browser's native paste.
async function performClipboardPaste(target, cache) {
    if (!target) return false;
    target.focus();

    if (cache && cache.text) {
        performPaste(target, cache.text, { externalClipboard: true });
        return true;
    }

    try {
        if (typeof navigator !== 'undefined' && navigator.clipboard?.readText) {
            const text = await navigator.clipboard.readText();
            if (text) {
                performPaste(target, text, { externalClipboard: true });
                return true;
            }
        }
    } catch (e) {}

    try {
        if (document.execCommand && document.execCommand('paste')) {
            showPasteResultToast('', false, false, true);
            return true;
        }
    } catch (e) {}

    showToast(t('toast_paste_fail'));
    return false;
}

// Core paste logic: synthetic paste first, then DOM/execCommand fallbacks.
function performPaste(target, text, options = {}) {
    if (!target) return;
    const panCode = Boolean(options.panCode);
    const externalClipboard = Boolean(options.externalClipboard);
    target.focus();

    // Strategy 1: emit the same event a real Ctrl+V would emit.
    const valueBefore = target.isContentEditable ? target.textContent : target.value;
    const pasteHandled = dispatchPasteEvent(target, text);
    const valueAfter = target.isContentEditable ? target.textContent : target.value;
    if (pasteHandled || valueAfter !== valueBefore) {
        showPasteResultToast(text, panCode, false, externalClipboard);
        return;
    }

    // Strategy 2: document.execCommand (preserves undo, fires native events)
    try {
        const success = document.execCommand('insertText', false, text);
        if (success) {
            showPasteResultToast(text, panCode, false, externalClipboard);
            return;
        }
    } catch (e) {}

    // Strategy 3: Direct assignment + dispatch events (Vue/React compat)
    try {
        if (target.isContentEditable) {
            const sel = window.getSelection();
            if (sel.rangeCount > 0) {
                const range = sel.getRangeAt(0);
                range.deleteContents();
                range.insertNode(document.createTextNode(text));
                range.collapse(false);
            } else {
                target.innerText += text;
            }
        } else {
            const start = target.selectionStart || 0;
            const end = target.selectionEnd || 0;
            const oldVal = target.value;
            const newVal = oldVal.slice(0, start) + text + oldVal.slice(end);

            let proto = window.HTMLInputElement.prototype;
            if (target.tagName === 'TEXTAREA') {
                proto = window.HTMLTextAreaElement.prototype;
            }

            const nativeValueSetter = Object.getOwnPropertyDescriptor(proto, "value").set;
            if (nativeValueSetter && nativeValueSetter.call) {
                nativeValueSetter.call(target, newVal);
            } else {
                target.value = newVal;
            }

            target.dispatchEvent(new Event('input', { bubbles: true }));
            target.dispatchEvent(new Event('change', { bubbles: true }));

            const newCursorPos = start + text.length;
            target.setSelectionRange(newCursorPos, newCursorPos);
        }
        showPasteResultToast(text, panCode, true, externalClipboard);
    } catch (e) {
        showToast(t('toast_paste_fail'));
    }
}

// Snapshot the selection before an async clipboard write. Inputs keep their
// selectionStart/End; contenteditable editors need the live Range cloned.
function captureSelectionSnapshot(target) {
    if (!target) return null;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
        const start = target.selectionStart;
        const end = target.selectionEnd;
        return typeof start === 'number' && typeof end === 'number'
            ? { start, end }
            : null;
    }
    const selection = window.getSelection();
    return selection && selection.rangeCount > 0
        ? selection.getRangeAt(0).cloneRange()
        : null;
}

const makeInputEvent = (type, inputType) => {
    if (typeof InputEvent === 'function') {
        return new InputEvent(type, {
            bubbles: true,
            cancelable: type === 'beforeinput',
            inputType,
            data: null
        });
    }
    return new Event(type, { bubbles: true, cancelable: type === 'beforeinput' });
};

// Replace [start, end) in an input/textarea through the native setter so
// React/Vue state and the caret stay coherent.
function replaceInputRange(target, start, end, replacement, selectReplacement = false) {
    const proto = target.tagName === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    const next = target.value.slice(0, start) + replacement + target.value.slice(end);
    if (setter) setter.call(target, next);
    else target.value = next;

    const caret = start + replacement.length;
    if (selectReplacement && replacement.length > 0) {
        target.setSelectionRange(start, caret);
    } else {
        target.setSelectionRange(caret, caret);
    }
    target.dispatchEvent(new Event('input', { bubbles: true }));
    target.dispatchEvent(new Event('change', { bubbles: true }));
}

// Delete the current selection in a way editors can follow. execCommand alone
// is not enough: Vditor (markdown.lovejade.cn) copies on cut but prevents the
// default deletion, leaving its contenteditable untouched.
function deleteSelectedText(target, snapshot = null) {
    if (!target) return false;

    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
        target.focus();
        const start = snapshot && typeof snapshot.start === 'number'
            ? snapshot.start
            : target.selectionStart;
        const end = snapshot && typeof snapshot.end === 'number'
            ? snapshot.end
            : target.selectionEnd;
        if (typeof start !== 'number' || typeof end !== 'number' || start === end) return false;

        target.setSelectionRange(start, end);
        if (!target.dispatchEvent(makeInputEvent('beforeinput', 'deleteByCut'))) return false;

        const oldValue = target.value;
        const newValue = oldValue.slice(0, start) + oldValue.slice(end);
        const proto = target.tagName === 'TEXTAREA'
            ? window.HTMLTextAreaElement.prototype
            : window.HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;

        if (setter) setter.call(target, newValue);
        else target.value = newValue;

        target.setSelectionRange(start, start);
        target.dispatchEvent(makeInputEvent('input', 'deleteByCut'));
        target.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
    }

    if (!target.isContentEditable) return false;

    const selection = window.getSelection();
    if (snapshot && snapshot instanceof Range && selection) {
        selection.removeAllRanges();
        selection.addRange(snapshot);
    }
    target.focus();

    const textBefore = target.textContent;

    // Native deletion drives most editors' beforeinput/input pipeline.
    try {
        document.execCommand('delete');
    } catch (e) {}

    if (target.textContent !== textBefore) return true;

    const liveSelection = window.getSelection();
    if (!liveSelection || liveSelection.rangeCount === 0 || liveSelection.isCollapsed) {
        return false;
    }

    const range = liveSelection.getRangeAt(0);
    if (!target.dispatchEvent(makeInputEvent('beforeinput', 'deleteByCut'))) return true;

    range.deleteContents();
    liveSelection.removeAllRanges();
    liveSelection.addRange(range);
    target.dispatchEvent(makeInputEvent('input', 'deleteByCut'));
    target.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
}


// ---- 16-blocker.js ----
// Module 16: Element Blocker Subsystem

let pickerOverlay = null;
let pickerHandler = null;
let pickerClickHandler = null;
let pickerEscHandler = null;
let pickerRightClickHandler = null;

// Auto-apply saved blocking rules
function applySavedBlockingRules() {
    const rules = configCache['blocked_elements'] || {};
    const domain = location.hostname;
    if (rules[domain] && Array.isArray(rules[domain])) {
        const cssText = rules[domain].join(', ') + ' { display: none !important; visibility: hidden !important; opacity: 0 !important; pointer-events: none !important; }';
        GM_addStyle(cssText);
    }
}

// Activate picker mode
function activateElementPicker() {
    if (pickerOverlay) disablePicker();

    showToast(t('picker_active'));

    // Create highlight overlay
    pickerOverlay = document.createElement('div');
    pickerOverlay.style.all = 'initial';
    pickerOverlay.style.position = 'fixed';
    pickerOverlay.style.pointerEvents = 'none';
    pickerOverlay.style.border = '2px solid #ff0000';
    pickerOverlay.style.background = 'rgba(255, 0, 0, 0.1)';
    pickerOverlay.style.zIndex = '2147483646';
    pickerOverlay.style.transition = 'all 0.1s ease';
    pickerOverlay.style.display = 'none';
    document.body.appendChild(pickerOverlay);

    pickerHandler = (e) => {
        const target = e.target;
        if (target === hostElement || hostElement.contains(target) || target === pickerOverlay) return;
        const rect = target.getBoundingClientRect();
        pickerOverlay.style.display = 'block';
        pickerOverlay.style.top = rect.top + 'px';
        pickerOverlay.style.left = rect.left + 'px';
        pickerOverlay.style.width = rect.width + 'px';
        pickerOverlay.style.height = rect.height + 'px';
    };

    pickerClickHandler = (e) => {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        const target = e.target;
        if (target === hostElement || hostElement.contains(target)) {
            showToast(t('picker_cant_block_self'));
            return;
        }

        const selector = generateCssSelector(target);
        if (confirm(t('picker_confirm', selector) + `\n(Domain: ${location.hostname})`)) {
            saveBlockRule(selector);
            target.style.display = 'none';
            showToast(t('picker_saved'));
            disablePicker();
        }
    };

    pickerEscHandler = (e) => {
        if (e.key === 'Escape') {
            disablePicker();
            showToast(t('picker_exit'));
        }
    };

    pickerRightClickHandler = (e) => {
        e.preventDefault();
        e.stopPropagation();
        disablePicker();
    };

    document.addEventListener('contextmenu', pickerRightClickHandler, true);
    document.addEventListener('mousemove', pickerHandler, true);
    document.addEventListener('click', pickerClickHandler, true);
    document.addEventListener('keydown', pickerEscHandler, true);
}

// Exit picker mode
function disablePicker() {
    if (pickerOverlay) {
        pickerOverlay.remove();
        pickerOverlay = null;
    }
    document.removeEventListener('mousemove', pickerHandler, true);
    document.removeEventListener('click', pickerClickHandler, true);
    document.removeEventListener('keydown', pickerEscHandler, true);
    document.removeEventListener('contextmenu', pickerRightClickHandler, true);
    pickerRightClickHandler = null;
}

// Generate the shortest possible unique CSS selector
function generateCssSelector(el) {
    if (el.id) return '#' + CSS.escape(el.id);

    const tagName = el.tagName.toLowerCase();
    let selector = tagName;

    if (el.className && typeof el.className === 'string' && el.className.trim().length > 0) {
        const classes = el.className.trim().split(/\s+/);
        classes.slice(0, 3).forEach(c => {
            selector += '.' + CSS.escape(c);
        });
    }

    if (selector === tagName) {
        if (el.parentElement && el.parentElement !== document.body) {
            return generateCssSelector(el.parentElement) + ' > ' + tagName;
        }
    }

    return selector;
}

// Save rule to GM storage
function saveBlockRule(selector) {
    const rules = configCache['blocked_elements'] || {};
    const domain = location.hostname;

    if (!rules[domain]) rules[domain] = [];
    if (!rules[domain].includes(selector)) {
        rules[domain].push(selector);
        configCache['blocked_elements'] = rules;
        safeSetValue('blocked_elements', rules);
    }
}


// ---- 17-festival.js ----
// Module 17: Festival Emoji Effects

const FESTIVAL_GRAVITY = 0.22;

// Emoji particles burst upward, then fall under one shared gravity model. Each
// particle owns its speed, direction, size and fade time; it disappears after
// its own lifetime, never based on travel distance.
function triggerFestivalEffect(x, y, shadowRoot) {
    if (getConfig('disableFestivalEffect')) return;
    const festival = getFestivalInfo();
    if (!festival || !festival.emojis.length) return;

    const particleCount = 24 + Math.floor(Math.random() * 16);
    const fragment = document.createDocumentFragment();

    for (let i = 0; i < particleCount; i++) {
        const p = document.createElement('div');
        const size = 16 + Math.random() * 16;
        const emoji = festival.emojis[Math.floor(Math.random() * festival.emojis.length)];

        p.textContent = emoji;
        p.style.cssText = `
            position: fixed;
            left: ${x}px;
            top: ${y}px;
            font-size: ${size}px;
            line-height: 1;
            pointer-events: none;
            user-select: none;
            z-index: 2147483647;
            will-change: transform, opacity;
        `;

        const vx = (Math.random() - 0.5) * 2 * (2 + Math.random() * 3);
        let vy = -(4 + Math.random() * 5);
        const lifetime = 900 + Math.random() * 1400;
        const fadeStart = lifetime * (0.45 + Math.random() * 0.2);
        const start = performance.now();
        let last = start;
        let posX = 0;
        let posY = 0;

        const animate = (now) => {
            const age = now - start;
            if (age >= lifetime) {
                p.remove();
                return;
            }

            // Normalize to 60fps steps so particles move the same on any refresh rate.
            const step = Math.min(48, now - last) / 16.6667;
            last = now;
            posX += vx * step;
            posY += vy * step;
            vy += FESTIVAL_GRAVITY * step;
            p.style.transform = `translate3d(${posX}px, ${posY}px, 0)`;
            p.style.opacity = age >= fadeStart
                ? String(1 - (age - fadeStart) / (lifetime - fadeStart))
                : '1';

            requestAnimationFrame(animate);
        };

        fragment.appendChild(p);
        requestAnimationFrame(animate);
    }

    shadowRoot.appendChild(fragment);
}

// Get toast copy text
function getFestivalToastText() {
    const festival = getFestivalInfo();
    if (!festival) return t('toast_copied');
    const emoji = festival.emojis[0];
    return `${emoji}${t('toast_copied')}${emoji}`;
}


// ---- 18-canvas-text.js ----
// Module 18: Canvas fillText Text Extraction (Super Selection)

// Hooked fillText calls are recorded per canvas so a hotkey+click can return
// the real text arguments. Records are cleared after a successful copy, and a
// canvas resize/reset discards the stale frame.
const canvasTextStore = new WeakMap();
const CANVAS_TEXT_LIMIT = 500;
const CANVAS_LINE_TOLERANCE = 5;

function getCanvasTextRecord(canvas) {
    const existing = canvasTextStore.get(canvas);
    if (existing && existing.width === canvas.width && existing.height === canvas.height) {
        return existing;
    }
    const record = {
        width: canvas.width,
        height: canvas.height,
        entries: [],
        keys: new Set()
    };
    canvasTextStore.set(canvas, record);
    return record;
}

function recordCanvasText(canvas, text, x, y) {
    if (!canvas || typeof text !== 'string' || !text) return;
    const record = getCanvasTextRecord(canvas);
    const key = `${text}\u0000${Math.round(x)}\u0000${Math.round(y)}`;
    if (record.keys.has(key)) return;
    record.keys.add(key);
    record.entries.push({ text, x, y, key });
    if (record.entries.length > CANVAS_TEXT_LIMIT) {
        record.keys.delete(record.entries.shift().key);
    }
}

// Group recorded draws into visual lines and read left to right, top to bottom.
function composeCanvasText(record) {
    if (!record || record.entries.length === 0) return '';
    const sorted = record.entries
        .slice()
        .sort((a, b) => (a.y - b.y) || (a.x - b.x));

    const lines = [];
    for (const entry of sorted) {
        const line = lines[lines.length - 1];
        if (line && Math.abs(entry.y - line.y) < CANVAS_LINE_TOLERANCE) {
            line.entries.push(entry);
        } else {
            lines.push({ y: entry.y, entries: [entry] });
        }
    }

    return lines
        .map((line) => line.entries
            .sort((a, b) => a.x - b.x)
            .map((entry) => entry.text)
            .join(''))
        .filter((line) => line.trim())
        .join('\n');
}

let canvasTextHookInstalled = false;

function installCanvasTextHook() {
    if (canvasTextHookInstalled) return true;
    const proto = typeof CanvasRenderingContext2D !== 'undefined'
        ? CanvasRenderingContext2D.prototype
        : null;
    if (!proto || typeof proto.fillText !== 'function') return false;

    const originalFillText = proto.fillText;
    const hookedFillText = function (text, x, y) {
        try {
            recordCanvasText(this.canvas, text, x, y);
        } catch (e) {}
        return originalFillText.apply(this, arguments);
    };
    hookedFillText.__scCanvasTextHook = true;
    proto.fillText = hookedFillText;

    window.addEventListener('click', copyCanvasTextOnClick, true);
    canvasTextHookInstalled = true;
    return true;
}

function findCanvasInEvent(e) {
    const path = typeof e.composedPath === 'function' ? e.composedPath() : [e.target];
    for (const node of path) {
        if (node && node.tagName === 'CANVAS') return node;
    }
    return null;
}

async function copyCanvasTextOnClick(e) {
    if (!isUnlockMode) return;
    const canvas = findCanvasInEvent(e);
    if (!canvas) return;

    // The toast lives inside the toolbar's shadow root.
    initContainer();
    const record = canvasTextStore.get(canvas);
    const text = composeCanvasText(record);
    if (!text) {
        showToast(t('toast_canvas_empty'));
        return;
    }
    if (!(await copyToClipboard(text, ''))) {
        showToast(t('toast_paste_fail'));
        return;
    }
    // A later repaint should describe the next frame, not replay this one.
    if (record) {
        record.entries.length = 0;
        record.keys.clear();
    }
    showToast(t('toast_canvas_copied', text.length));
}



// ---- 19-bootstrap.js ----
// Module 19: Bootstrap

// Lightning paste conditional visibilitychange cleanup (dynamic register/unregister)
// Unregister listener when copy/cut writes cache, register when paste resets timestamp
// On page hidden: overwrite with expired cache (never actively delete, one-way overwrite only)
// Note: these two functions must be defined in global scope because onclick callbacks in renderButton need to access them
let _visibilityChangeHandler = null;

function registerVisibilityCleanup() {
    if (_visibilityChangeHandler) return;
    _visibilityChangeHandler = async () => {
        if (document.visibilityState === 'hidden') {
            if (getConfig('enablePaste')) {
                await safeSetValue('smart_paste_cache', { text: '', timestamp: 0 });
            }
            unregisterVisibilityCleanup();
        }
    };
    document.addEventListener('visibilitychange', _visibilityChangeHandler, false);
}

function unregisterVisibilityCleanup() {
    if (_visibilityChangeHandler) {
        document.removeEventListener('visibilitychange', _visibilityChangeHandler, false);
        _visibilityChangeHandler = null;
    }
}

// Host-facing readiness: userscript menus are registered only after the
// toolbar has loaded its configuration, so menu actions never see an empty
// configCache.
let resolveToolbarReady = null;
const toolbarReady = new Promise((resolve) => {
    resolveToolbarReady = resolve;
});

function markToolbarReady() {
    if (!resolveToolbarReady) return;
    resolveToolbarReady();
    resolveToolbarReady = null;
}

(function () {
    'use strict';

    (async function main() {
        try {
            // 0. Install before anything awaits: every fillText after this point
            //    is recorded, so a later super-selection click can copy it.
            installCanvasTextHook();

            // 1. Wait for config to load
            await initConfiguration();

            // Auto-set default search engine based on timezone on first run
            await initDefaultSearchEngine();
            markToolbarReady();

            // 2. Apply blocking rules (userscript menu commands are registered
            //    by the host from the user-defined menu order).
            applySavedBlockingRules();

            // 4. In unlock mode, smart intercept Ctrl+scroll
            const handleWheelZoom = (e) => {
                if (!e.ctrlKey || !isUnlockMode) return;

                const hotkey = getConfig('unlockHotkey') || '';
                const isCtrlConfigured = hotkey.includes('Control') || hotkey.toLowerCase() === 'ctrl';

                if (isCtrlConfigured) {
                    e.preventDefault();
                    e.stopPropagation();
                    window.scrollBy({
                        top: e.deltaY,
                        behavior: 'auto'
                    });
                }
            };
            window.addEventListener('wheel', handleWheelZoom, { passive: false, capture: true });

            // 5. Register all event listeners
            // Capture phase: shadow-DOM hosts and page widgets may stop mouseup
            // from bubbling, which used to suppress the toolbar entirely.
            window.addEventListener('mouseup', handleSelectionMouseUp, true);
            document.addEventListener('mouseup', handleInputPasteMouseUp, true);
            document.addEventListener('mousedown', handleGlobalMouseDown, false);
            document.addEventListener('contextmenu', handleContextMenu, true);
            window.addEventListener('scroll', handleResizeOrScroll, { passive: true });
            window.addEventListener('resize', handleResizeOrScroll, { passive: true });
            document.addEventListener('keydown', handleKeydownHideUI, true);
            // Capture copies made outside the toolbar; registered before unlock
            // mode's stopImmediatePropagation listener so it always sees them.
            window.addEventListener('copy', handleExternalCopy, true);

            // Copy button for <pre><code> blocks follows the hover target.
            document.addEventListener('mouseover', handleCodeCopyHover, true);
            window.addEventListener('scroll', hideCodeCopyButton, { passive: true, capture: true });
            window.addEventListener('resize', hideCodeCopyButton, { passive: true });
            window.addEventListener('blur', hideCodeCopyButton);

            // 6. Drag preview event listeners (main window only)
            if (window.name !== PREVIEW_WIN_NAME) {
                document.addEventListener('dragstart', handleLinkDragStart, false);
                document.addEventListener('dragend', handleLinkDragEnd, false);
            }

        } catch (e) {
            markToolbarReady();
            //console.error('Smart Copy startup failed:', e);
        }
    })();
})();


// ---- 20-code-copy.js ----
// Module 20: Hover copy button for <pre><code> blocks

const CODE_COPY_EDGE_GAP = 8;
const CODE_COPY_ANCHOR_GAP = 6;

let codeCopyButton = null;
let codeCopyTarget = null;

// Any <pre> with text: some highlighters (cnblogs/hljs) render spans straight
// into the <pre> and drop the <code> wrapper, so requiring `pre code` misses
// them. Line-number helpers are empty elements drawn by CSS and do not pollute
// textContent.
function findCodeBlock(target) {
    const pre = target?.closest?.('pre');
    if (!pre || !String(pre.textContent || '').trim()) return null;
    return pre;
}

// Sit inside the block's top-right corner, clear of its border/padding.
function getCodeCopyPosition(rect, size) {
    const left = Math.max(
        CODE_COPY_EDGE_GAP,
        Math.min(
            rect.right - size.width - CODE_COPY_ANCHOR_GAP,
            window.innerWidth - size.width - CODE_COPY_EDGE_GAP
        )
    );
    const top = rect.top + CODE_COPY_ANCHOR_GAP;
    return {
        left,
        top: Math.max(
            CODE_COPY_EDGE_GAP,
            Math.min(top, window.innerHeight - size.height - CODE_COPY_EDGE_GAP)
        ),
    };
}

function getCodeBlockText(pre) {
    const code = pre.querySelector('code') || pre;
    // Keep indentation, only drop the newlines that templates add around it.
    return String(code.textContent || '').replace(/^\n+|\n+$/g, '');
}

async function copyCodeBlock(pre) {
    const text = getCodeBlockText(pre);
    if (!text) return false;
    const copied = await copyToClipboard(text, '');
    if (copied) showToast(t('toast_copied'));
    return copied;
}

function ensureCodeCopyButton() {
    if (!hostElement) initContainer();
    if (codeCopyButton && codeCopyButton.isConnected) return codeCopyButton;

    const container = document.createElement('div');
    container.className = 'sc-container sc-code-copy';
    container.setAttribute('data-btn-count', '1');
    container.classList.add(
        getConfig('forceWhiteBlack') ? 'theme-light-ui' : getBestContrastTheme()
    );

    const btn = document.createElement('div');
    btn.className = 'sc-btn';
    btn.title = t('btn_copy');
    btn.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>`;
    btn.onmousedown = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };
    btn.onclick = async (e) => {
        e.preventDefault();
        e.stopPropagation();
        const pre = codeCopyTarget;
        hideCodeCopyButton();
        if (pre && pre.isConnected) await copyCodeBlock(pre);
    };
    container.appendChild(btn);

    // A click meant for this button must not reach page copy/selection handlers.
    ['pointerdown', 'mousedown', 'click', 'dblclick'].forEach((type) => {
        container.addEventListener(type, (e) => e.stopPropagation());
    });

    shadowRoot.appendChild(container);
    codeCopyButton = container;
    return container;
}

function hideCodeCopyButton() {
    codeCopyTarget = null;
    if (codeCopyButton) codeCopyButton.classList.remove('visible');
}

function showCodeCopyButton(pre) {
    if (!pre.isConnected) {
        hideCodeCopyButton();
        return;
    }
    const rect = pre.getBoundingClientRect();
    if (!rect.width || !rect.height) {
        hideCodeCopyButton();
        return;
    }

    const container = ensureCodeCopyButton();
    codeCopyTarget = pre;
    const position = getCodeCopyPosition(rect, {
        width: container.offsetWidth,
        height: container.offsetHeight,
    });
    container.style.left = `${position.left}px`;
    container.style.top = `${position.top}px`;
    container.classList.add('visible');
}

function handleCodeCopyHover(e) {
    if (isUnlockMode) return;
    const path = typeof e.composedPath === 'function' ? e.composedPath() : [];
    if (hostElement && path.includes(hostElement)) return;

    const pre = findCodeBlock(e.target);
    if (!pre) {
        hideCodeCopyButton();
        return;
    }
    showCodeCopyButton(pre);
}


